"use client"

import { useEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"
import { useDictionary } from "@/hooks/use-dictionary"
import { cn } from "@/lib/utils"

export type ExportFormat = "drawio" | "png" | "svg" | "xmlsvg"

// The PNG background choice, kept in this browser for the next exports
const TRANSPARENT_PNG_KEY = "next-ai-draw-io-png-transparent"
// The choice made in this page, kept only while storage is full or blocked
// (otherwise the stored one counts, as another tab may have changed it)
let transparentChoice: boolean | null = null

/** The user asked for PNG exports without a background (saveDiagramToFile
 * reads this; the dialog sets it before calling onSave) */
export function prefersTransparentPng(): boolean {
    if (transparentChoice !== null) return transparentChoice
    try {
        return localStorage.getItem(TRANSPARENT_PNG_KEY) === "true"
    } catch {
        return false
    }
}

function setTransparentPng(transparent: boolean) {
    try {
        localStorage.setItem(TRANSPARENT_PNG_KEY, String(transparent))
        transparentChoice = null
    } catch {
        // Kept for this page only
        transparentChoice = transparent
    }
}

interface SaveDialogProps {
    open: boolean
    onOpenChange: (open: boolean) => void
    onSave: (filename: string, format: ExportFormat) => void
    defaultFilename: string
}

export function SaveDialog({
    open,
    onOpenChange,
    onSave,
    defaultFilename,
}: SaveDialogProps) {
    const dict = useDictionary()
    const [filename, setFilename] = useState(defaultFilename)
    const [format, setFormat] = useState<ExportFormat>("drawio")
    const [transparent, setTransparent] = useState(false)
    const inputRef = useRef<HTMLInputElement>(null)
    // The name used last time, while the default name is still the same
    // (the same chat)
    const lastNameRef = useRef<{ forDefault: string; name: string } | null>(
        null,
    )

    // The default name (or the last one used) each time the dialog opens;
    // a chat title that comes while it is open (the chat is saved
    // meanwhile) keeps what was typed
    const wasOpenRef = useRef(false)
    useEffect(() => {
        if (open && !wasOpenRef.current) {
            const last = lastNameRef.current
            setFilename(
                last?.forDefault === defaultFilename
                    ? last.name
                    : defaultFilename,
            )
            setTransparent(prefersTransparentPng())
        }
        wasOpenRef.current = open
    }, [open, defaultFilename])

    const handleSave = () => {
        const finalFilename = filename.trim() || defaultFilename
        lastNameRef.current = {
            forDefault: defaultFilename,
            name: finalFilename,
        }
        if (format === "png") setTransparentPng(transparent)
        onSave(finalFilename, format)
        onOpenChange(false)
    }

    const handleKeyDown = (e: React.KeyboardEvent) => {
        // Enter that picks an IME candidate (Safari: keyCode 229)
        if (e.nativeEvent.isComposing || e.keyCode === 229) return
        if (e.key === "Enter") {
            e.preventDefault()
            handleSave()
        }
    }

    const FORMAT_OPTIONS = [
        {
            value: "drawio" as const,
            label: dict.save.formats.drawio,
            hint: dict.save.hints.drawio,
            extension: ".drawio",
        },
        {
            value: "png" as const,
            label: dict.save.formats.png,
            hint: dict.save.hints.png,
            extension: ".png",
        },
        {
            value: "svg" as const,
            label: dict.save.formats.svg,
            hint: dict.save.hints.svg,
            extension: ".svg",
        },
        {
            value: "xmlsvg" as const,
            label: dict.save.formats.xmlsvg,
            hint: dict.save.hints.xmlsvg,
            extension: ".drawio.svg",
        },
    ]

    const currentFormat = FORMAT_OPTIONS.find((f) => f.value === format)

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-lg">
                <DialogHeader>
                    <DialogTitle>{dict.save.title}</DialogTitle>
                    <DialogDescription>
                        {dict.save.description}
                    </DialogDescription>
                </DialogHeader>
                <div className="space-y-4">
                    <div
                        role="radiogroup"
                        aria-label={dict.save.format}
                        className="grid grid-cols-2 gap-2"
                    >
                        {FORMAT_OPTIONS.map((opt) => (
                            // biome-ignore lint/a11y/useSemanticElements: styled radio tile
                            <button
                                key={opt.value}
                                type="button"
                                role="radio"
                                aria-checked={format === opt.value}
                                onClick={(e) => {
                                    setFormat(opt.value)
                                    // After a mouse click (detail > 0) on a
                                    // screen without touch, back to the
                                    // name, selected, so typing replaces it.
                                    // A keyboard user stays in the formats;
                                    // a touch screen would open its keyboard
                                    if (
                                        e.detail > 0 &&
                                        !window.matchMedia("(pointer: coarse)")
                                            .matches
                                    ) {
                                        inputRef.current?.focus()
                                    }
                                }}
                                className={cn(
                                    "rounded-lg border border-border p-3 text-left transition-colors hover:border-foreground/30",
                                    format === opt.value &&
                                        "border-foreground bg-accent",
                                )}
                            >
                                <span className="block text-[13px] font-medium text-foreground">
                                    {opt.label}
                                </span>
                                <span className="mt-0.5 block text-xs text-muted-foreground">
                                    {opt.hint}
                                </span>
                            </button>
                        ))}
                    </div>
                    {format === "png" && (
                        <label className="flex w-fit items-center gap-2 text-sm">
                            <input
                                type="checkbox"
                                checked={transparent}
                                onChange={(e) =>
                                    setTransparent(e.target.checked)
                                }
                                className="size-4 accent-foreground"
                            />
                            {dict.save.transparentBackground}
                        </label>
                    )}
                    <div className="space-y-2">
                        <label
                            htmlFor="export-filename"
                            className="text-sm font-medium"
                        >
                            {dict.save.filename}
                        </label>
                        {/* One field: the name, then its extension */}
                        <div className="flex h-9 items-center overflow-hidden rounded-md border border-input focus-within:ring-2 focus-within:ring-ring/40">
                            <input
                                ref={inputRef}
                                id="export-filename"
                                value={filename}
                                onChange={(e) => setFilename(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder={dict.save.filenamePlaceholder}
                                autoFocus
                                onFocus={(e) => e.target.select()}
                                className="h-full min-w-0 flex-1 bg-transparent px-3 text-sm outline-none"
                            />
                            <span className="shrink-0 pr-3 text-sm text-muted-foreground">
                                {currentFormat?.extension}
                            </span>
                        </div>
                    </div>
                </div>
                <DialogFooter>
                    <Button
                        variant="outline"
                        onClick={() => onOpenChange(false)}
                    >
                        {dict.common.cancel}
                    </Button>
                    <Button onClick={handleSave}>
                        {dict.workspace.export}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}
"use client"

import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { XIcon } from "lucide-react"

import { useDictionary } from "@/hooks/use-dictionary"
import { cn } from "@/lib/utils"

function Dialog({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-black/40 backdrop-blur-[2px]",
        "data-[state=open]:animate-in data-[state=closed]:animate-out",
        "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
        "duration-200",
        className
      )}
      {...props}
    />
  )
}

function DialogContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content>) {
  const dict = useDictionary()
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          // Base styles
          "fixed top-[50%] left-[50%] z-50 w-full",
          "max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%]",
          "grid gap-4 p-6",
          // Refined visual treatment
          "bg-surface-0 rounded-2xl border border-border-subtle shadow-pop",
          // Entry/exit animations
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
          "data-[state=closed]:zoom-out-[0.98] data-[state=open]:zoom-in-[0.98]",
          "data-[state=closed]:slide-out-to-top-[2%] data-[state=open]:slide-in-from-top-[2%]",
          "duration-200 sm:max-w-lg",
          className
        )}
        {...props}
      >
        {children}
        <DialogPrimitive.Close className={cn(
          "absolute top-4 right-4 rounded-xl p-1.5",
          "text-muted-foreground/60 hover:text-foreground",
          "hover:bg-interactive-hover",
          "transition-all duration-150",
          "focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
          "disabled:pointer-events-none",
          "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg]:size-4"
        )}>
          <XIcon />
          <span className="sr-only">{dict.common.close}</span>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-2 text-center sm:text-left", className)}
      {...props}
    />
  )
}

function DialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn(
        "flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    />
  )
}

function DialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn(
        "text-xl font-semibold tracking-tight leading-tight",
        className
      )}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn(
        "text-sm text-muted-foreground leading-relaxed",
        className
      )}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
}
"use client"

import type React from "react"
import {
    createContext,
    useCallback,
    useContext,
    useEffect,
    useRef,
    useState,
} from "react"
import { toast } from "sonner"
import type {
    DrawioExportEvent,
    DrawioFrameHandle,
} from "@/components/canvas/drawio-frame"
import {
    type ExportFormat,
    prefersTransparentPng,
} from "@/components/save-dialog"
import { getApiEndpoint } from "@/lib/base-path"
import { withPageDefaults } from "@/lib/drawio/drawio-config"
import {
    canReplaceDiagram,
    commitDiagram,
    fitOpenedDiagram,
    previewDiagram,
    resetPreview,
    revertPreview,
    selectPage,
} from "@/lib/drawio/editor-bridge"
import { formatMessage } from "@/lib/i18n/utils"
import {
    BLANK_MXFILE,
    normalizeToMxfile,
} from "@/packages/mcp-server/src/pages.ts"
import { validateAndFixXml } from "@/packages/mcp-server/src/xml-validation.ts"
import { useCanvasStore } from "@/stores/canvas-store"
import { extractDiagramXML, isRealDiagram } from "../lib/utils"

/**
 * How a diagram reaches the canvas:
 * - load: replace the whole document and reset undo (sessions, new chat)
 * - preview: streaming AI output, not recorded in undo history
 * - commit: final AI result, one undo step; reported to commit listeners
 * - revert: drop the streaming preview and go back to the given diagram
 *
 * preview/commit/revert go through the draw.io editor when it is reachable
 * (same origin); otherwise they fall back to a full load.
 */
export type LoadMode = "load" | "preview" | "commit" | "revert"

/** The document without where its view was scrolled to (dx, dy) */
function withoutView(xml: string): string {
    return xml.replace(/<mxGraphModel\b[^>]*>/g, (tag) =>
        tag.replace(/\s(?:dx|dy)="[^"]*"/g, ""),
    )
}

interface LoadMeta {
    toolCallId?: string
    pageId?: string | null
    keepView?: boolean
}

export interface DiagramCommit {
    beforeXml: string
    afterXml: string
    toolCallId?: string
    /** The page the change was made on; null or absent: the first page */
    pageId?: string | null
}

/** An export as draw.io's export action takes it: the format, and for PNG
 * its scale, width cap and the page to render (pageId) */
export interface ExportRequest {
    format: string
    [key: string]: unknown
}

/** What draw.io answered: the image (a data URL, or SVG text) in data; for
 * format "xml" the document in xml instead */
export interface ExportResult {
    data?: string
    xml?: string
}

interface DiagramContextType {
    chartXML: string
    // chartXML right away, before the re-render (loadDiagram sets both)
    chartXMLRef: React.MutableRefObject<string>
    // The diagram's latest SVG export, a fallback thumbnail for saves
    latestSvgRef: React.MutableRefObject<string>
    /** keepView: a load leaves the view as it is (it is fitted otherwise:
     * the web app's loads open a chat or a file) */
    loadDiagram: (
        chart: string,
        skipValidation?: boolean,
        mode?: LoadMode,
        meta?: LoadMeta,
    ) => string | null
    /** The XML of the page on screen, exported from draw.io */
    fetchDiagramXml: () => Promise<string>
    drawioRef: React.MutableRefObject<DrawioFrameHandle | null>
    handleDiagramExport: (data: DrawioExportEvent) => void
    handleDiagramAutoSave: (data: { xml?: string }) => void
    clearDiagram: () => void
    saveDiagramToFile: (
        filename: string,
        format: ExportFormat,
        sessionId?: string,
        successMessage?: string,
    ) => Promise<void>
    getThumbnailSvg: () => Promise<string | null>
    getVersionSvg: () => Promise<string | null>
    captureValidationPng: () => Promise<string | null>
    /** One export with its own result; null when draw.io does not answer
     * in time (the MCP shell answers the server's export requests with it) */
    requestExport: (
        request: ExportRequest,
        timeoutMs?: number,
    ) => Promise<ExportResult | null>
    /** Show a document for an export only (the MCP's one-page projection of
     * another page): not recorded as the diagram, its autosaves ignored,
     * until the next loadDiagram puts the real document back */
    showTransient: (xml: string) => void
    /** A full load was sent and draw.io has not reported it yet: the
     * editor still shows the previous document */
    hasPendingLoad: () => boolean
    isDrawioReady: boolean
    onDrawioLoad: () => void
    resetDrawioReady: () => void
    /** Register the handler told about every committed AI change */
    setCommitHandler: (
        handler: ((commit: DiagramCommit) => void) | null,
    ) => void
    /** A new user turn starts: forget the streaming base */
    startTurn: () => void
}

const DiagramContext = createContext<DiagramContextType | undefined>(undefined)

// Every export carries a tag in the request's `message` field. draw.io
// echoes the request back in the export event, so each result reaches its
// own caller. Tags end in a request number, so a late result never answers
// a newer request.
type ExportTag = "thumbnail" | "validation" | "version" | "fetch"

export function DiagramProvider({ children }: { children: React.ReactNode }) {
    const [chartXML, setChartXML] = useState<string>("")
    const latestSvgRef = useRef("")
    const [isDrawioReady, setIsDrawioReady] = useState(false)
    const hasCalledOnLoadRef = useRef(false)
    const mountedRef = useRef(true)
    useEffect(() => {
        mountedRef.current = true
        return () => {
            mountedRef.current = false
        }
    }, [])
    const drawioRef = useRef<DrawioFrameHandle | null>(null)
    // Pending exports, keyed by their export tag
    const exportResolversRef = useRef<
        Record<string, (result: ExportResult) => void>
    >({})
    const exportSeqRef = useRef(0)
    // Track latest chartXML for restoration after remount
    const chartXMLRef = useRef<string>("")
    // Diagram before the current AI change started streaming
    const turnBaseRef = useRef<string | null>(null)
    // Full loads sent that draw.io has not reported done yet
    const pendingLoadsRef = useRef(0)
    const commitHandlerRef = useRef<((commit: DiagramCommit) => void) | null>(
        null,
    )

    // The page to show again once a full load is done: draw.io shows the
    // first page of a loaded document
    const pageAfterLoadRef = useRef<string | null>(null)
    // The last full load sent opens a diagram (a saved chat, a file): fit
    // it into view once it is done (draw.io keeps the scroll position)
    const fitAfterLoadRef = useRef(false)
    // A transient document (showTransient) is on the canvas, and the page
    // the user was on before it
    const transientRef = useRef(false)
    const pageBeforeTransientRef = useRef<string | null>(null)

    // Sends a full load. draw.io runs it when its message arrives, and then
    // reports "load": until then the editor shows the diagram from before,
    // so later changes go the same way and keep their order
    const fullLoad = (
        xml: string,
        pageId: string | null = useCanvasStore.getState().currentPageId,
        fit = false,
    ) => {
        if (!drawioRef.current) return
        pageAfterLoadRef.current =
            pageId && xml.includes(`id="${pageId}"`) ? pageId : null
        fitAfterLoadRef.current = fit
        pendingLoadsRef.current++
        drawioRef.current.load({ xml })
    }

    const onDrawioLoad = () => {
        pendingLoadsRef.current = Math.max(0, pendingLoadsRef.current - 1)
        // Back to the page the user was on, once the last load sent is on
        // the canvas: the page belongs to that load (an earlier one that
        // draw.io reports first is replaced right after)
        if (pendingLoadsRef.current === 0) {
            const pageId = pageAfterLoadRef.current
            pageAfterLoadRef.current = null
            if (pageId) selectPage(pageId)
        }
        // Only set ready state once to prevent infinite loops
        if (hasCalledOnLoadRef.current) {
            if (fitAfterLoadRef.current && pendingLoadsRef.current === 0) {
                fitAfterLoadRef.current = false
                fitOpenedDiagram()
            }
            return
        }
        hasCalledOnLoadRef.current = true
        setIsDrawioReady(true)
        // draw.io's first load: loads sent before it went nowhere
        pendingLoadsRef.current = 0
        // Restore diagram after remount (e.g., theme/UI change), or a file
        // opened while draw.io loaded (its page settings count too)
        if (chartXMLRef.current) fullLoad(chartXMLRef.current, undefined, true)
    }

    const resetDrawioReady = () => {
        hasCalledOnLoadRef.current = false
        pendingLoadsRef.current = 0
        setIsDrawioReady(false)
    }

    // Update chartXML and its ref together, so callbacks that read the ref
    // (export handler, autosave) see the new value right away
    const updateChartXML = (xml: string) => {
        chartXMLRef.current = xml
        setChartXML(xml)
    }

    // Export with a tag in `message` (draw.io echoes it back in the export
    // event) and wait for that result. Resolves to null on timeout, which is
    // expected occasionally.
    // (Reads refs only, so it keeps one identity)
    const requestTaggedExport = useCallback(
        (tag: ExportTag, format: "xmlsvg" | "svg" | "png", timeoutMs: number) =>
            new Promise<ExportResult | null>((resolve) => {
                const id = `${tag}-${++exportSeqRef.current}`
                const finish = (value: ExportResult | null) => {
                    clearTimeout(timer)
                    delete exportResolversRef.current[id]
                    resolve(value)
                }
                const timer = setTimeout(() => finish(null), timeoutMs)
                exportResolversRef.current[id] = finish
                drawioRef.current?.exportDiagram({ format, message: id })
            }),
        [],
    )

    // Get current diagram as SVG for thumbnail (used by session storage).
    // One identity: the chat's auto-save effect depends on it
    const getThumbnailSvg = useCallback(async (): Promise<string | null> => {
        if (!drawioRef.current) return null
        // Don't export if diagram is empty
        if (!isRealDiagram(chartXMLRef.current)) return null

        // xmlsvg exports return an SVG data URL
        const result = await requestTaggedExport("thumbnail", "xmlsvg", 3000)
        if (result?.data?.startsWith("data:image/svg")) {
            // Kept for later saves that take no fresh thumbnail
            latestSvgRef.current = result.data
            return result.data
        }
        return null
    }, [requestTaggedExport])

    // Plain SVG (no embedded diagram data) for version cards
    const getVersionSvg = async (): Promise<string | null> => {
        if (!drawioRef.current) return null
        const result = await requestTaggedExport("version", "svg", 4000)
        return result?.data?.startsWith("data:image/svg") ? result.data : null
    }

    // Capture current diagram as PNG for VLM validation
    const captureValidationPng = async (): Promise<string | null> => {
        if (!drawioRef.current) return null
        // Don't export if diagram is empty
        if (!isRealDiagram(chartXMLRef.current)) return null

        const result = await requestTaggedExport("validation", "png", 5000)
        // PNG data should be a base64 data URL
        return result?.data?.startsWith("data:image/png") ? result.data : null
    }

    // The page the user is viewing (the first one with an external draw.io,
    // which cannot tell us), for the chat and edit_diagram.
    // Not written to chartXML: exports don't change the diagram, and the
    // export's xml has compressed <diagram> payloads that would break
    // edit_diagram/display_diagram. Autosave keeps chartXML up to date with
    // the full uncompressed multi-page document (#879).
    const fetchDiagramXml = async (): Promise<string> => {
        const result = await requestTaggedExport("fetch", "xmlsvg", 10000)
        if (!result?.data) {
            throw new Error("Chart export timed out after 10 seconds")
        }
        latestSvgRef.current = result.data
        return extractDiagramXML(
            result.data,
            useCanvasStore.getState().currentPageId,
        )
    }

    // Like requestTaggedExport, with the request's other parameters (a PNG's
    // page and width) and both parts of the answer
    const requestExport = useCallback(
        (request: ExportRequest, timeoutMs = 10000) =>
            new Promise<ExportResult | null>((resolve) => {
                if (!drawioRef.current) {
                    resolve(null)
                    return
                }
                const id = `export-${++exportSeqRef.current}`
                const finish = (value: ExportResult | null) => {
                    clearTimeout(timer)
                    delete exportResolversRef.current[id]
                    resolve(value)
                }
                const timer = setTimeout(() => finish(null), timeoutMs)
                exportResolversRef.current[id] = finish
                drawioRef.current.exportDiagram({ ...request, message: id })
            }),
        [],
    )

    const showTransient = (xml: string) => {
        if (!transientRef.current) {
            pageBeforeTransientRef.current =
                useCanvasStore.getState().currentPageId
        }
        transientRef.current = true
        fullLoad(xml)
    }

    const loadDiagram = (
        chart: string,
        skipValidation?: boolean,
        mode: LoadMode = "load",
        meta?: LoadMeta,
    ): string | null => {
        // The editor bridge is shared: a page that is gone (another language
        // mounted a new one) must not change the new page's canvas
        if (!mountedRef.current) return null
        // A real document ends a transient one; the user goes back to the
        // page they were on before it
        const pageBeforeTransient = transientRef.current
            ? pageBeforeTransientRef.current
            : undefined
        transientRef.current = false
        let xmlToLoad = chart

        // Validate XML structure before loading (unless skipped for internal
        // use). Not strict: the XML may hold the user's own diagram, and the
        // tool handlers check model XML strictly before it gets here.
        if (!skipValidation) {
            const validation = validateAndFixXml(chart, { strict: false })
            if (!validation.valid) {
                console.warn(
                    "[loadDiagram] Validation error:",
                    validation.error,
                )
                return validation.error
            }
            // Use fixed XML if auto-fix was applied
            if (validation.fixed) {
                console.log(
                    "[loadDiagram] Auto-fixed XML issues:",
                    validation.fixes,
                )
                xmlToLoad = validation.fixed
            }
        }

        xmlToLoad = withPageDefaults(xmlToLoad)

        const previousXml = chartXMLRef.current
        if (mode === "preview" && turnBaseRef.current === null) {
            turnBaseRef.current = previousXml
        }
        const beforeXml = turnBaseRef.current ?? previousXml
        if (mode !== "preview") turnBaseRef.current = null

        // Keep chartXML in sync even when diagrams are injected (e.g., display_diagram tool)
        updateChartXML(xmlToLoad)

        let applied = false
        if (
            mode !== "load" &&
            pendingLoadsRef.current === 0 &&
            canReplaceDiagram(xmlToLoad)
        ) {
            try {
                if (mode === "preview") previewDiagram(xmlToLoad)
                else if (mode === "commit") commitDiagram(xmlToLoad)
                else revertPreview(xmlToLoad)
                applied = true
            } catch (error) {
                console.warn("[loadDiagram] Editor update failed:", error)
            }
        }
        if (!applied) {
            // A full load replaces any preview, and its base is stale now
            resetPreview()
            fullLoad(
                xmlToLoad,
                pageBeforeTransient ?? meta?.pageId ?? undefined,
                mode === "load" && !meta?.keepView,
            )
        }

        if (mode === "commit") {
            commitHandlerRef.current?.({
                beforeXml,
                afterXml: xmlToLoad,
                toolCallId: meta?.toolCallId,
                pageId: meta?.pageId,
            })
        }

        return null
    }

    const startTurn = () => {
        turnBaseRef.current = null
        resetPreview()
    }

    // Each export result goes to the caller that asked for it, by its tag
    const handleDiagramExport = (data: DrawioExportEvent) => {
        const tag = data.message?.message
        if (!tag) return
        exportResolversRef.current[tag]?.({ data: data.data, xml: data.xml })
    }

    // The frame registers this callback once per iframe mount, so it must
    // read refs: state captured in its closure would stay stale after a remount
    const handleDiagramAutoSave = (data: { xml?: string }) => {
        if (!data?.xml) return
        // An edit of a transient document is not the diagram's; nor is one
        // of the canvas a full load still on its way replaces (draw.io
        // reports each load, in order, so no autosave of the new document
        // comes before that)
        if (transientRef.current || pendingLoadsRef.current > 0) return
        // Don't overwrite a pending restore - if we have a diagram but
        // DrawIO hasn't loaded yet, it means we're waiting to restore
        if (!hasCalledOnLoadRef.current && chartXMLRef.current) return
        // Only the view moved, or draw.io saved what it just loaded: nothing
        // changed, and a save would put a chat that was only opened first
        // in the list
        if (withoutView(data.xml) === withoutView(chartXMLRef.current)) return
        updateChartXML(data.xml)
    }

    const clearDiagram = () => {
        const emptyDiagram = BLANK_MXFILE
        // Skip validation for trusted internal template (loadDiagram also sets chartXML)
        loadDiagram(emptyDiagram, true)
        latestSvgRef.current = ""
    }

    const saveDiagramToFile = async (
        filename: string,
        format: ExportFormat,
        sessionId?: string,
        successMessage?: string,
    ) => {
        // Map format to draw.io export format
        const drawioFormat =
            format === "drawio" || format === "xmlsvg" ? "xmlsvg" : format
        // Pictures get a margin; a PNG twice the size, of the page on
        // screen (draw.io renders the first page otherwise), on white
        // unless the user asked for a transparent background
        const imageOptions =
            format === "drawio"
                ? {}
                : format === "png"
                  ? {
                        border: 20,
                        scale: 2,
                        currentPage: true,
                        ...(prefersTransparentPng()
                            ? { transparent: true }
                            : { background: "#ffffff" }),
                    }
                  : { border: 20 }

        // Each save has its own request id, so two at once never swap
        // results. A large PNG takes a while to render.
        const result = await requestExport(
            { format: drawioFormat, ...imageOptions },
            30000,
        )
        if (!result?.data) {
            console.warn(
                "Diagram export for saving failed (editor not ready or timed out)",
            )
            return
        }
        const exportData = result.data
        const fullDiagramXML = result.xml
        let fileContent: string
        let mimeType: string
        let extension: string

        if (format === "drawio") {
            // Prefer the complete document from the export event so all pages are saved.
            const xml = fullDiagramXML?.trim()
                ? fullDiagramXML
                : extractDiagramXML(exportData)
            fileContent =
                normalizeToMxfile(xml, {
                    pageId: "page-1",
                    pageName: "Page-1",
                }) ?? xml
            mimeType = "application/xml"
            extension = ".drawio"
        } else if (format === "png") {
            // PNG data comes as base64 data URL
            fileContent = exportData
            mimeType = "image/png"
            extension = ".png"
        } else if (format === "xmlsvg") {
            // Editable SVG: pass data URL directly (like PNG)
            fileContent = exportData
            mimeType = "image/svg+xml"
            extension = ".drawio.svg"
        } else {
            // SVG format (view-only)
            fileContent = exportData
            mimeType = "image/svg+xml"
            extension = ".svg"
        }

        // Log save event to Langfuse (flags the trace)
        logSaveToLangfuse(filename, format, sessionId)

        // Handle download
        let url: string
        if (fileContent.startsWith("data:")) {
            // Already a data URL (PNG)
            url = fileContent
        } else {
            const blob = new Blob([fileContent], { type: mimeType })
            url = URL.createObjectURL(blob)
        }

        const a = document.createElement("a")
        a.href = url
        a.download = `${filename}${extension}`
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)

        // Show success toast after download is initiated
        if (successMessage) {
            toast.success(formatMessage(successMessage, { name: a.download }), {
                duration: 4000,
            })
        }

        // Delay URL revocation to ensure download completes
        if (!url.startsWith("data:")) {
            setTimeout(() => URL.revokeObjectURL(url), 100)
        }
    }

    // Log save event to Langfuse (just flags the trace, doesn't send content)
    const logSaveToLangfuse = async (
        filename: string,
        format: string,
        sessionId?: string,
    ) => {
        try {
            await fetch(getApiEndpoint("/api/log-save"), {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ filename, format, sessionId }),
            })
        } catch (error) {
            console.warn("Failed to log save to Langfuse:", error)
        }
    }

    const setCommitHandler = (
        handler: ((commit: DiagramCommit) => void) | null,
    ) => {
        commitHandlerRef.current = handler
    }

    return (
        <DiagramContext.Provider
            value={{
                chartXML,
                chartXMLRef,
                latestSvgRef,
                loadDiagram,
                fetchDiagramXml,
                drawioRef,
                handleDiagramExport,
                handleDiagramAutoSave,
                clearDiagram,
                saveDiagramToFile,
                getThumbnailSvg,
                getVersionSvg,
                captureValidationPng,
                requestExport,
                showTransient,
                hasPendingLoad: () => pendingLoadsRef.current > 0,
                isDrawioReady,
                onDrawioLoad,
                resetDrawioReady,
                setCommitHandler,
                startTurn,
            }}
        >
            {children}
        </DiagramContext.Provider>
    )
}

export function useDiagram() {
    const context = useContext(DiagramContext)
    if (context === undefined) {
        throw new Error("useDiagram must be used within a DiagramProvider")
    }
    return context
}
/**
 * XML validation and auto-fix for draw.io diagrams, shared by the MCP server
 * and the web app (contexts/diagram-context.tsx)
 */

import { readAttributes } from "./xml-attributes.ts"
import { getXmlSyntaxError } from "./xml-syntax.ts"

// ============================================================================
// Constants
// ============================================================================

/** Structural attributes that should not be duplicated in draw.io */
const STRUCTURAL_ATTRS = [
    "edge",
    "parent",
    "source",
    "target",
    "vertex",
    "connectable",
]

/** Element names draw.io understands (case-sensitive) */
const VALID_DRAWIO_TAGS = new Set([
    "mxfile",
    "diagram",
    "mxGraphModel",
    "root",
    "mxCell",
    "mxGeometry",
    "mxPoint",
    "Array",
    "Object",
    "mxRectangle",
    // Wrappers draw.io writes for cells with links, tooltips or data
    "UserObject",
    "object",
])

// ============================================================================
// XML Parsing Helpers
// ============================================================================

interface ParsedTag {
    tag: string
    tagName: string
    isClosing: boolean
    isSelfClosing: boolean
    startIndex: number
    endIndex: number
}

/**
 * Parse XML tags while properly handling quoted strings
 */
function parseXmlTags(xml: string): ParsedTag[] {
    const tags: ParsedTag[] = []
    let i = 0

    while (i < xml.length) {
        const tagStart = xml.indexOf("<", i)
        if (tagStart === -1) break

        // Find matching > by tracking quotes
        let tagEnd = tagStart + 1
        let inQuote = false
        let quoteChar = ""

        while (tagEnd < xml.length) {
            const c = xml[tagEnd]
            if (inQuote) {
                if (c === quoteChar) inQuote = false
            } else {
                if (c === '"' || c === "'") {
                    inQuote = true
                    quoteChar = c
                } else if (c === ">") {
                    break
                }
            }
            tagEnd++
        }

        if (tagEnd >= xml.length) break

        const tag = xml.substring(tagStart, tagEnd + 1)
        i = tagEnd + 1

        const tagMatch = /^<(\/?)([a-zA-Z][a-zA-Z0-9:_-]*)/.exec(tag)
        if (!tagMatch) continue

        tags.push({
            tag,
            tagName: tagMatch[2],
            isClosing: tagMatch[1] === "/",
            isSelfClosing: tag.endsWith("/>"),
            startIndex: tagStart,
            endIndex: tagEnd,
        })
    }

    return tags
}

/**
 * Returns a function telling whether a position lies inside a quoted
 * attribute value. Positions must be queried in increasing order.
 */
function createQuoteTracker(str: string): (pos: number) => boolean {
    let i = 0
    let inQuote = false
    let quoteChar = ""
    return (pos: number) => {
        for (; i < pos && i < str.length; i++) {
            const c = str[i]
            if (inQuote) {
                if (c === quoteChar) inQuote = false
            } else if (c === '"' || c === "'") {
                // Only quotes that follow "=" open an attribute value
                let j = i - 1
                while (j >= 0 && /\s/.test(str[j])) j--
                if (j >= 0 && str[j] === "=") {
                    inQuote = true
                    quoteChar = c
                }
            }
        }
        return inQuote
    }
}

/** Rewrite every opening tag with fn, leaving text and closing tags as is. */
function replaceInOpeningTags(
    xml: string,
    fn: (tag: string) => string,
): string {
    let out = ""
    let last = 0
    for (const { tag, isClosing, startIndex, endIndex } of parseXmlTags(xml)) {
        if (isClosing) continue
        out += xml.slice(last, startIndex) + fn(tag)
        last = endIndex + 1
    }
    return out + xml.slice(last)
}

// ============================================================================
// Validation Helper Functions
// ============================================================================

/** Check for duplicate structural attributes in a tag */
function checkDuplicateAttributes(xml: string): string | null {
    const structuralSet = new Set(STRUCTURAL_ATTRS)
    for (const [tag] of xml.matchAll(/<[^>]+>/g)) {
        const attributes = new Map<string, number>()
        for (const { name } of readAttributes(tag)) {
            attributes.set(name, (attributes.get(name) || 0) + 1)
        }
        const duplicates = Array.from(attributes.entries())
            .filter(([name, count]) => count > 1 && structuralSet.has(name))
            .map(([name]) => name)
        if (duplicates.length > 0) {
            return `Invalid XML: Duplicate structural attribute(s): ${duplicates.join(", ")}. Remove duplicate attributes.`
        }
    }
    return null
}

/**
 * Check for duplicate IDs in XML.
 *
 * For multi-page documents (<mxfile> with multiple <diagram> children), cell
 * IDs are unique **within a page**, not across the whole document — drawio
 * legitimately reuses "0" and "1" for the root cells of every page. So we
 * scope the cell-ID uniqueness check per <diagram>, and additionally check
 * that the <diagram> ids themselves are unique.
 *
 * The legacy regex-based check is kept as a fallback for non-mxfile inputs.
 */
function checkDuplicateIds(xml: string): string | null {
    // The DOM-aware path only matters for <mxfile> wrappers; for legacy
    // bare <mxGraphModel> inputs (the overwhelming majority of historic
    // traffic), the cheap regex fallback at the bottom is enough. A quick
    // string check avoids paying the DOMParser cost on every call.
    const mightBeMxFile = /<mxfile[\s>]/i.test(xml)

    // Try DOM-aware, page-scoped check first when the input looks mxfile-ish.
    if (mightBeMxFile) {
        const doc = new DOMParser().parseFromString(xml, "text/xml")
        const rootEl = doc.documentElement
        if (rootEl && rootEl.tagName === "mxfile") {
            const diagrams = doc.querySelectorAll("diagram")

            // 1) <diagram> ids must be unique across the file.
            const diagramIds = new Map<string, number>()
            diagrams.forEach((d) => {
                const id = d.getAttribute("id")
                if (id) diagramIds.set(id, (diagramIds.get(id) || 0) + 1)
            })
            const dupDiagrams = Array.from(diagramIds.entries())
                .filter(([, c]) => c > 1)
                .map(([id]) => `'${id}'`)
            if (dupDiagrams.length > 0) {
                return `Invalid XML: Found duplicate <diagram> id(s): ${dupDiagrams.slice(0, 3).join(", ")}. Each page must have a unique id.`
            }

            // 2) Within each page, cell ids must be unique. A cell with
            // a link or custom data is a UserObject/object holding the
            // id, around an mxCell whose own id does not count.
            for (let i = 0; i < diagrams.length; i++) {
                const diagram = diagrams[i]
                const pageId = diagram.getAttribute("id") || `(index ${i})`
                const cells = diagram.querySelectorAll(
                    "mxCell, UserObject, object",
                )
                const cellIds = new Map<string, number>()
                cells.forEach((c) => {
                    const wrapped =
                        c.tagName === "mxCell" &&
                        /^(UserObject|object)$/.test(
                            c.parentElement?.tagName ?? "",
                        )
                    const id = c.getAttribute("id")
                    if (id && !wrapped)
                        cellIds.set(id, (cellIds.get(id) || 0) + 1)
                })
                const dups = Array.from(cellIds.entries())
                    .filter(([, c]) => c > 1)
                    .map(([id, count]) => `'${id}' (${count}x)`)
                if (dups.length > 0) {
                    return `Invalid XML: Found duplicate cell ID(s) in page "${pageId}": ${dups.slice(0, 3).join(", ")}. All mxCell ids must be unique within a page.`
                }
            }
            return null
        }
    }

    // Legacy regex-based check for bare <mxGraphModel> inputs.
    const idPattern = /\bid\s*=\s*["']([^"']+)["']/gi
    const ids = new Map<string, number>()
    let idMatch
    while ((idMatch = idPattern.exec(xml)) !== null) {
        const id = idMatch[1]
        ids.set(id, (ids.get(id) || 0) + 1)
    }
    const duplicateIds = Array.from(ids.entries())
        .filter(([, count]) => count > 1)
        .map(([id, count]) => `'${id}' (${count}x)`)
    if (duplicateIds.length > 0) {
        return `Invalid XML: Found duplicate ID(s): ${duplicateIds.slice(0, 3).join(", ")}. All id attributes must be unique.`
    }
    return null
}

/** Check for nested mxCell tags using regex */
function checkNestedMxCells(xml: string): string | null {
    // Quoted values may hold ">", so the tag ends at the first ">" outside them
    const cellTagPattern = /<\/?mxCell\b(?:[^<>"']|"[^"]*"|'[^']*')*>/g
    const cellStack: number[] = []
    let cellMatch
    while ((cellMatch = cellTagPattern.exec(xml)) !== null) {
        const tag = cellMatch[0]
        const nested =
            "Invalid XML: Found nested mxCell tags. Cells should be siblings, not nested inside other mxCell elements."
        const isLabelOrGeometry =
            /\sas\s*=\s*["'](valueLabel|geometry)["']/.test(tag)
        if (tag.startsWith("</mxCell>")) {
            if (cellStack.length > 0) cellStack.pop()
        } else if (tag.endsWith("/>")) {
            // A self-closing cell inside an open one is nested too (or the
            // open one lacks its </mxCell>; the auto-fix sorts that out)
            if (cellStack.length > 0 && !isLabelOrGeometry) return nested
        } else if (!isLabelOrGeometry) {
            cellStack.push(cellMatch.index)
            if (cellStack.length > 1) return nested
        }
    }
    return null
}

/** Check for element names draw.io does not know (e.g. a lowercase <mxcell>) */
function checkUnknownElements(xml: string): string | null {
    const tags = parseXmlTags(xml.replace(/<!--[\s\S]*?-->/g, ""))
    for (const { tagName } of tags) {
        if (!VALID_DRAWIO_TAGS.has(tagName)) {
            return `Invalid XML: Unknown element <${tagName}>. draw.io only understands ${Array.from(VALID_DRAWIO_TAGS).join(", ")} (names are case-sensitive).`
        }
    }
    return null
}

/**
 * Find <mxPoint> elements without an "as" attribute outside <Array
 * as="points">. draw.io rejects them with "Could not add object mxPoint".
 */
function findOrphanMxPoints(
    xml: string,
): Array<{ start: number; end: number }> {
    const arrays: Array<[number, number]> = []
    // (?<!\/) skips an empty <Array/>, which has no points inside
    for (const m of xml.matchAll(/<Array\b[^>]*(?<!\/)>[\s\S]*?<\/Array>/g)) {
        arrays.push([m.index, m.index + m[0].length])
    }
    const orphans: Array<{ start: number; end: number }> = []
    for (const m of xml.matchAll(/<mxPoint\b[^>]*?(?:\/>|>\s*<\/mxPoint>)/g)) {
        if (/\sas\s*=/.test(m[0])) continue
        if (arrays.some(([s, e]) => m.index > s && m.index < e)) continue
        orphans.push({ start: m.index, end: m.index + m[0].length })
    }
    return orphans
}

// ============================================================================
// Main Validation Function
// ============================================================================

/**
 * Validates draw.io XML structure for common issues
 * Uses DOM parsing + additional regex checks for high accuracy
 * @param xml - The XML string to validate
 * @param opts.strict - Also reject unknown element names and orphan
 *   <mxPoint>s. Used for XML the model wrote, not for files or browser state.
 * @returns null if valid, error message string if invalid
 */
/** The first non-blank text under el, skipping a page's compressed data */
function findTextBetweenTags(el: Element | null): string | null {
    if (!el) return null
    // A <diagram> with only text holds the page compressed
    const compressed = el.tagName === "diagram" && el.children.length === 0
    for (const node of Array.from(el.childNodes)) {
        if (node.nodeType === 1) {
            const text = findTextBetweenTags(node as Element)
            if (text) return text
        } else if (
            // Text, or a CDATA section (draw.io reads it as text too)
            (node.nodeType === 3 || node.nodeType === 4) &&
            !compressed
        ) {
            const text = node.textContent?.trim()
            if (text) return text.slice(0, 40)
        }
    }
    return null
}

export function validateMxCellStructure(
    xml: string,
    opts: { strict?: boolean } = {},
): string | null {
    // 0. DOM-based checks. Syntax errors are caught by the strict check at
    // the end: linkedom's DOMParser never reports them. The recursive text
    // walk overflows the stack on XML nested thousands of levels deep; the
    // checks below still run then, and auto-fix can repair it.
    try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(xml, "text/xml")

        // DOM-based checks for nested mxCell
        const allCells = doc.querySelectorAll("mxCell")
        for (const cell of allCells) {
            if (cell.parentElement?.tagName === "mxCell") {
                const id = cell.getAttribute("id") || "unknown"
                return `Invalid XML: Found nested mxCell (id="${id}"). Cells should be siblings, not nested inside other mxCell elements.`
            }
        }

        // draw.io reads any text inside a page as compressed page data and
        // then fails to open the page
        if (!doc.querySelector("parsererror")) {
            const text = findTextBetweenTags(doc.documentElement)
            if (text) {
                return `Invalid XML: Found text "${text}" between tags. Labels belong in the value attribute; remove any other text between tags.`
            }
        }
    } catch (error) {
        console.warn(
            "[validateMxCellStructure] DOM checks failed, falling back to regex validation:",
            error,
        )
    }

    // 1. Check for duplicate structural attributes
    const dupAttrError = checkDuplicateAttributes(xml)
    if (dupAttrError) {
        return dupAttrError
    }

    // 2. Check for duplicate IDs
    const dupIdError = checkDuplicateIds(xml)
    if (dupIdError) {
        return dupIdError
    }

    // 3. Check for empty id attributes on mxCell
    if (/<mxCell[^>]*\sid\s*=\s*["']\s*["'][^>]*>/g.test(xml)) {
        return "Invalid XML: Found mxCell element(s) with empty id attribute"
    }

    // 4. Check for nested mxCell tags
    const nestedCellError = checkNestedMxCells(xml)
    if (nestedCellError) {
        return nestedCellError
    }

    if (opts.strict) {
        const unknownError = checkUnknownElements(xml)
        if (unknownError) {
            return unknownError
        }
        if (findOrphanMxPoints(xml).length > 0) {
            return 'Invalid XML: Found <mxPoint> without an "as" attribute outside <Array as="points">. Put waypoints inside <Array as="points"> or remove the point.'
        }
    }

    // 5. Strict XML syntax check (saxes), which reports every
    // well-formedness error: unbalanced tags, bad character or entity
    // references, an unescaped < or &, duplicate or unquoted attributes.
    // Any of them makes draw.io refuse to load the diagram.
    const syntaxError = getXmlSyntaxError(xml)
    if (syntaxError) {
        return `Invalid XML: syntax error at ${syntaxError} Escape special characters in attribute values (&lt; for <, &amp; for &, &quot; for "), quote every attribute value, and do not repeat an attribute.`
    }

    return null
}

// ============================================================================
// Auto-Fix Function
// ============================================================================

/**
 * Attempts to auto-fix common XML issues in draw.io diagrams
 * @param xml - The XML string to fix
 * @returns Object with fixed XML and list of fixes applied
 */
/**
 * A compact cell's last attribute is a number, and the model sometimes
 * drops its closing quote: h="112/>. Only a cell whose earlier attributes
 * are all properly quoted is touched, so a label that happens to contain
 * such text is left alone.
 */
export function repairQuoteBeforeSlash(xml: string): string {
    return xml.replace(
        /<mxCell\b((?:\s+[\w:.-]+="[^"]*")*)(\s+(?:x|y|w|h|width|height)="-?\d+(?:\.\d+)?)\s*\/>/g,
        '<mxCell$1$2"/>',
    )
}

export function autoFixXml(xml: string): { fixed: string; fixes: string[] } {
    let fixed = xml
    const fixes: string[] = []

    // 0. Fix JSON-escaped XML
    if (/=\\"/.test(fixed)) {
        fixed = fixed.replace(/\\"/g, '"')
        fixed = fixed.replace(/\\n/g, "\n")
        fixes.push("Fixed JSON-escaped XML")
    }

    // 0b. Literal \n, \t or \r between tags, from escaping the XML twice
    const unescaped = fixed.replace(/>(?:\s|\\[nrt])+</g, (gap) =>
        gap.replace(/\\n/g, "\n").replace(/\\t/g, "\t").replace(/\\r/g, ""),
    )
    if (unescaped !== fixed) {
        fixed = unescaped
        fixes.push("Replaced literal \\n between tags with line breaks")
    }

    // 1. Remove CDATA wrapper
    if (/^\s*<!\[CDATA\[/.test(fixed)) {
        fixed = fixed.replace(/^\s*<!\[CDATA\[/, "").replace(/\]\]>\s*$/, "")
        fixes.push("Removed CDATA wrapper")
    }

    // 2. Remove text before XML declaration or root element
    const xmlStart = fixed.search(/<(\?xml|mxGraphModel|mxfile)/i)
    if (xmlStart > 0 && !/^<[a-zA-Z]/.test(fixed.trim())) {
        fixed = fixed.substring(xmlStart)
        fixes.push("Removed text before XML root")
    }

    // 3. Fix duplicate attributes
    let dupAttrFixed = false
    const structural = new Set(STRUCTURAL_ATTRS)
    fixed = fixed.replace(/<[^>]+>/g, (tag) => {
        // Keep the first of each, drop the later ones
        const seen = new Set<string>()
        let newTag = ""
        let last = 0
        for (const attr of readAttributes(tag)) {
            if (!structural.has(attr.name)) continue
            if (!seen.has(attr.name)) {
                seen.add(attr.name)
                continue
            }
            newTag += tag.slice(last, attr.start)
            last = attr.end
            dupAttrFixed = true
        }
        return newTag + tag.slice(last)
    })
    if (dupAttrFixed) {
        fixes.push("Removed duplicate structural attributes")
    }

    // 4. Fix unescaped & characters
    const ampersandPattern =
        /&(?!(?:lt|gt|amp|quot|apos|#[0-9]+|#x[0-9a-fA-F]+);)/g
    if (ampersandPattern.test(fixed)) {
        fixed = fixed.replace(
            /&(?!(?:lt|gt|amp|quot|apos|#[0-9]+|#x[0-9a-fA-F]+);)/g,
            "&amp;",
        )
        fixes.push("Escaped unescaped & characters")
    }

    // 6. Fix malformed attribute quotes (name=&quot;value&quot;). Quoted
    // values are matched first and kept, so &quot; inside a rich-text
    // label like value="&lt;font style=&quot;...&quot;&gt;" is left alone.
    let quotesFixed = false
    fixed = replaceInOpeningTags(fixed, (tag) =>
        tag.replace(
            /("[^"]*"|'[^']*')|(\s[a-zA-Z][a-zA-Z0-9_:-]*)=&quot;([^&]*?)&quot;/g,
            (match, quoted, name, value) => {
                if (quoted) return match
                quotesFixed = true
                return `${name}="${value}"`
            },
        ),
    )
    if (quotesFixed) {
        fixes.push("Fixed malformed attribute quotes")
    }

    // 6b. Missing closing quote on the last attribute of a compact cell
    // (h="112/>), see repairQuoteBeforeSlash
    const quoted = repairQuoteBeforeSlash(fixed)
    if (quoted !== fixed) {
        fixed = quoted
        fixes.push("Added a missing closing quote before />")
    }

    // 6c. A compact cell written without the slash: <mxCell ... h="60">
    // followed by the next cell, a definition or the end. Only cells that
    // carry a size or a connection, so an open container stays open.
    const slashless =
        /<mxCell\b((?:\s+[\w:.-]+="[^"]*")*)\s*>(?=\s*(?:<mxCell\b|<mxStyle\b|$))/g
    const closed = fixed.replace(slashless, (tag, attrText: string) =>
        /\s(?:x|y|w|h|width|height|source|target)="/.test(attrText)
            ? `<mxCell${attrText}/>`
            : tag,
    )
    if (closed !== fixed) {
        fixed = closed
        fixes.push("Closed compact cells written without the slash")
    }

    // 7. Fix malformed closing tags
    const malformedClosingTag = /<\/([a-zA-Z][a-zA-Z0-9]*)\s*\/>/g
    if (malformedClosingTag.test(fixed)) {
        fixed = fixed.replace(/<\/([a-zA-Z][a-zA-Z0-9]*)\s*\/>/g, "</$1>")
        fixes.push("Fixed malformed closing tags")
    }

    // 8. Fix missing space between attributes (id="2"vertex="1"). Every
    // quoted value is consumed whole, so quotes always pair up within one
    // attribute.
    let spaceAdded = false
    fixed = replaceInOpeningTags(fixed, (tag) =>
        tag.replace(
            /("[^"]*"|'[^']*')([a-zA-Z_:])?/g,
            (match, quoted, next) => {
                if (!next) return match
                spaceAdded = true
                return `${quoted} ${next}`
            },
        ),
    )
    if (spaceAdded) {
        fixes.push("Added missing space between attributes")
    }

    // 9. Fix unescaped quotes in style color values
    const quotedColorPattern = /;([a-zA-Z]*[Cc]olor)="#/
    if (quotedColorPattern.test(fixed)) {
        fixed = fixed.replace(/;([a-zA-Z]*[Cc]olor)="#/g, ";$1=#")
        fixes.push("Removed quotes around color values in style")
    }

    // 10. Fix unescaped < and > in attribute values
    // < is required to be escaped, > is not strictly required but we escape for consistency
    const hasUnescapedLt = /=\s*"[^"]*<[^"]*"/.test(fixed)
    if (hasUnescapedLt) {
        fixed = fixed.replace(/=\s*"([^"]*)"/g, (_match, value) => {
            const escaped = value.replace(/</g, "&lt;").replace(/>/g, "&gt;")
            return `="${escaped}"`
        })
        fixes.push("Escaped <> characters in attribute values")
    }

    // 13. Fix invalid comment syntax
    fixed = fixed.replace(/<!--([\s\S]*?)-->/g, (match, content) => {
        if (/--/.test(content)) {
            let fixedContent = content
            while (/--/.test(fixedContent)) {
                fixedContent = fixedContent.replace(/--/g, "-")
            }
            fixes.push("Fixed invalid comment syntax")
            return `<!--${fixedContent}-->`
        }
        return match
    })

    // 14. Fix <Cell> tags to <mxCell>
    const hasCellTags = /<\/?Cell[\s>]/i.test(fixed)
    if (hasCellTags) {
        fixed = fixed.replace(/<Cell(\s)/gi, "<mxCell$1")
        fixed = fixed.replace(/<Cell>/gi, "<mxCell>")
        fixed = fixed.replace(/<\/Cell>/gi, "</mxCell>")
        fixes.push("Fixed <Cell> tags to <mxCell>")
    }

    // 15. Fix closing tag typos and wrong tag case, e.g. <mxcell> (MUST run
    // before foreign tag removal, which would otherwise delete them)
    const before15 = fixed
    fixed = fixed.replace(/<\/mxElement>/gi, "</mxCell>")
    if (fixed !== before15) {
        fixes.push("Fixed typo </mxElement> to </mxCell>")
    }
    for (const name of ["mxCell", "mxGeometry", "mxPoint", "mxGraphModel"]) {
        let changed = false
        fixed = fixed.replace(
            new RegExp(`<(/?)${name}(?=[\\s/>])`, "gi"),
            (match, slash) => {
                const right = `<${slash}${name}`
                if (match !== right) changed = true
                return right
            },
        )
        if (changed) {
            fixes.push(`Fixed tag case of <${name}>`)
        }
    }

    // 16. Remove non-draw.io tags (after the case fixes above). Removes only
    // the exact tag occurrences and skips quoted attribute values, so a stray
    // <mxGraph/> never takes <mxGraphModel> with it and <b> inside
    // value="..." stays.
    const isInsideQuotesFor16 = createQuoteTracker(fixed)
    const foreignTagPattern = /<\/?([a-zA-Z][a-zA-Z0-9_]*)[^>]*>/g
    let foreignMatch
    const foreignTags = new Set<string>()
    const foreignTagPositions: Array<{ start: number; end: number }> = []
    while ((foreignMatch = foreignTagPattern.exec(fixed)) !== null) {
        const tagName = foreignMatch[1]
        if (VALID_DRAWIO_TAGS.has(tagName)) continue
        if (isInsideQuotesFor16(foreignMatch.index)) continue
        foreignTags.add(tagName)
        foreignTagPositions.push({
            start: foreignMatch.index,
            end: foreignMatch.index + foreignMatch[0].length,
        })
    }
    if (foreignTagPositions.length > 0) {
        // Remove from the end so earlier positions stay valid
        for (const { start, end } of foreignTagPositions.reverse()) {
            fixed = fixed.slice(0, start) + fixed.slice(end)
        }
        fixes.push(
            `Removed foreign tags: ${Array.from(foreignTags).join(", ")}`,
        )
    }

    // 16b. Remove orphan <mxPoint>s (no "as" attribute, not inside
    // <Array as="points">), which draw.io refuses to load
    const orphanPoints = findOrphanMxPoints(fixed)
    if (orphanPoints.length > 0) {
        for (const { start, end } of orphanPoints.reverse()) {
            fixed = fixed.slice(0, start) + fixed.slice(end)
        }
        fixes.push(`Removed ${orphanPoints.length} orphan <mxPoint>(s)`)
    }

    // 17. Fix unclosed tags
    const tagStack: string[] = []
    const parsedTags = parseXmlTags(fixed)

    for (const { tagName, isClosing, isSelfClosing } of parsedTags) {
        if (isClosing) {
            const lastIdx = tagStack.lastIndexOf(tagName)
            if (lastIdx !== -1) {
                tagStack.splice(lastIdx, 1)
            }
        } else if (!isSelfClosing) {
            tagStack.push(tagName)
        }
    }

    if (tagStack.length > 0) {
        const tagsToClose: string[] = []
        for (const tagName of tagStack.reverse()) {
            const openCount = (
                fixed.match(new RegExp(`<${tagName}[\\s>]`, "gi")) || []
            ).length
            const closeCount = (
                fixed.match(new RegExp(`</${tagName}>`, "gi")) || []
            ).length
            if (openCount > closeCount) {
                tagsToClose.push(tagName)
            }
        }
        if (tagsToClose.length > 0) {
            const closingTags = tagsToClose.map((t) => `</${t}>`).join("\n")
            fixed = fixed.trimEnd() + "\n" + closingTags
            fixes.push(
                `Closed ${tagsToClose.length} unclosed tag(s): ${tagsToClose.join(", ")}`,
            )
        }
    }

    // 18. Remove extra closing tags. Counts only draw.io tags outside quoted
    // attribute values (value="<b>Title</b>" holds HTML, not elements).
    const tagCounts = new Map<
        string,
        { opens: number; closes: number; selfClosing: number }
    >()
    const fullTagPattern = /<(\/?[a-zA-Z][a-zA-Z0-9]*)[^>]*>/g
    const isInsideQuotesFor18 = createQuoteTracker(fixed)
    let tagCountMatch
    while ((tagCountMatch = fullTagPattern.exec(fixed)) !== null) {
        if (isInsideQuotesFor18(tagCountMatch.index)) continue
        const fullMatch = tagCountMatch[0]
        const tagPart = tagCountMatch[1]
        const isClosing = tagPart.startsWith("/")
        const isSelfClosing = fullMatch.endsWith("/>")
        const tagName = isClosing ? tagPart.slice(1) : tagPart
        if (!VALID_DRAWIO_TAGS.has(tagName)) continue

        let counts = tagCounts.get(tagName)
        if (!counts) {
            counts = { opens: 0, closes: 0, selfClosing: 0 }
            tagCounts.set(tagName, counts)
        }
        if (isClosing) {
            counts.closes++
        } else if (isSelfClosing) {
            counts.selfClosing++
        } else {
            counts.opens++
        }
    }

    for (const [tagName, counts] of tagCounts) {
        const extraCloses = counts.closes - counts.opens
        if (extraCloses > 0) {
            let removed = 0
            const closeTagPattern = new RegExp(`</${tagName}>`, "g")
            const matches = [...fixed.matchAll(closeTagPattern)]
            for (
                let i = matches.length - 1;
                i >= 0 && removed < extraCloses;
                i--
            ) {
                const match = matches[i]
                const idx = match.index ?? 0
                fixed = fixed.slice(0, idx) + fixed.slice(idx + match[0].length)
                removed++
            }
            if (removed > 0) {
                fixes.push(
                    `Removed ${removed} extra </${tagName}> closing tag(s)`,
                )
            }
        }
    }

    // 19. Remove trailing garbage after last XML tag
    const closingTagPattern = /<\/[a-zA-Z][a-zA-Z0-9]*>|\/>/g
    let lastValidTagEnd = -1
    let closingMatch
    while ((closingMatch = closingTagPattern.exec(fixed)) !== null) {
        lastValidTagEnd = closingMatch.index + closingMatch[0].length
    }
    if (lastValidTagEnd > 0 && lastValidTagEnd < fixed.length) {
        const trailing = fixed.slice(lastValidTagEnd).trim()
        if (trailing) {
            fixed = fixed.slice(0, lastValidTagEnd)
            fixes.push("Removed trailing garbage after last XML tag")
        }
    }

    // 20. Fix nested mxCell by flattening
    const lines = fixed.split("\n")
    let newLines: string[] = []
    let nestedFixed = 0
    let extraClosingToRemove = 0

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        const nextLine = lines[i + 1]

        if (
            nextLine &&
            /<mxCell\s/.test(line) &&
            /<mxCell\s/.test(nextLine) &&
            !line.includes("/>") &&
            !nextLine.includes("/>")
        ) {
            const id1 = line.match(/\bid\s*=\s*["']([^"']+)["']/)?.[1]
            const id2 = nextLine.match(/\bid\s*=\s*["']([^"']+)["']/)?.[1]

            if (id1 && id1 === id2) {
                nestedFixed++
                extraClosingToRemove++
                continue
            }
        }

        if (extraClosingToRemove > 0 && /^\s*<\/mxCell>\s*$/.test(line)) {
            extraClosingToRemove--
            continue
        }

        newLines.push(line)
    }

    if (nestedFixed > 0) {
        fixed = newLines.join("\n")
        fixes.push(`Flattened ${nestedFixed} duplicate-ID nested mxCell(s)`)
    }

    // 21. Fix true nested mxCell (different IDs). Runs only when the nesting
    // check finds real nesting, because this line-based rewrite can break
    // valid cells written over several lines.
    const lines2 = checkNestedMxCells(fixed) ? fixed.split("\n") : []
    newLines = []
    let trueNestedFixed = 0
    let cellDepth = 0
    let pendingCloseRemoval = 0

    for (let i = 0; i < lines2.length; i++) {
        const line = lines2[i]
        const trimmed = line.trim()

        // A line holding a whole cell (<mxCell ...>...</mxCell>) opens nothing
        const isOpenCell =
            /<mxCell\s/.test(trimmed) &&
            !trimmed.endsWith("/>") &&
            !trimmed.endsWith("</mxCell>")
        // A self-closing (compact) cell is the next sibling too
        const isSelfClosingCell =
            /<mxCell\s/.test(trimmed) && trimmed.endsWith("/>")
        const isCloseCell = trimmed === "</mxCell>"
        // The last cell's closing tag may share its line with the wrapper's
        const startsWithClose = !isCloseCell && trimmed.startsWith("</mxCell>")

        if (isOpenCell || isSelfClosingCell) {
            if (cellDepth > 0) {
                const indent = line.slice(
                    0,
                    line.length - line.trimStart().length,
                )
                newLines.push(indent + "</mxCell>")
                trueNestedFixed++
                // The open cell's own </mxCell> is removed later, when there
                // is one before the next open cell; a cell that simply lacks
                // its closing tag has none to remove
                const nextOpen = lines2.findIndex(
                    (l, j) =>
                        j > i &&
                        /<mxCell\s/.test(l.trim()) &&
                        !l.trim().endsWith("/>"),
                )
                const nextClose = lines2.findIndex(
                    (l, j) => j > i && l.trim().startsWith("</mxCell>"),
                )
                if (
                    isOpenCell ||
                    (nextClose !== -1 &&
                        (nextOpen === -1 || nextClose < nextOpen))
                ) {
                    pendingCloseRemoval++
                }
            }
            cellDepth = isOpenCell ? 1 : 0
            newLines.push(line)
        } else if (isCloseCell) {
            if (pendingCloseRemoval > 0) {
                pendingCloseRemoval--
            } else {
                cellDepth = Math.max(0, cellDepth - 1)
                newLines.push(line)
            }
        } else if (startsWithClose && pendingCloseRemoval > 0) {
            pendingCloseRemoval--
            newLines.push(line.replace("</mxCell>", ""))
        } else {
            newLines.push(line)
        }
    }

    if (trueNestedFixed > 0) {
        fixed = newLines.join("\n")
        fixes.push(`Fixed ${trueNestedFixed} true nested mxCell(s)`)
    }

    // 22. Fix duplicate IDs by appending suffix.
    // Skipped for multi-page <mxfile> documents — cell ids "0" and "1" repeat
    // across pages legitimately (every page has its own <root> with id="0"/"1"
    // sentinel cells). Renaming them would break drawio's parent references.
    // For mxfile inputs, duplicate-id validation is page-scoped in
    // checkDuplicateIds() and a true duplicate produces a hard error rather
    // than a silent rename.
    if (!/<mxfile[\s>]/i.test(fixed)) {
        const seenIds = new Map<string, number>()
        const duplicateIds: string[] = []

        const idPattern = /\bid\s*=\s*["']([^"']+)["']/gi
        let idMatch
        while ((idMatch = idPattern.exec(fixed)) !== null) {
            const id = idMatch[1]
            seenIds.set(id, (seenIds.get(id) || 0) + 1)
        }

        for (const [id, count] of seenIds) {
            if (count > 1) duplicateIds.push(id)
        }

        if (duplicateIds.length > 0) {
            const idCounters = new Map<string, number>()
            // Rebuild from the captured parts so only the value changes (an id
            // like "d" or "i" also occurs in the attribute name itself)
            fixed = fixed.replace(
                /(\bid\s*=\s*["'])([^"']+)(["'])/gi,
                (match, before, id, after) => {
                    if (!duplicateIds.includes(id)) return match

                    const count = idCounters.get(id) || 0
                    idCounters.set(id, count + 1)

                    if (count === 0) return match

                    return `${before}${id}_dup${count}${after}`
                },
            )
            fixes.push(`Renamed ${duplicateIds.length} duplicate ID(s)`)
        }
    }

    // 23. Fix empty id attributes
    let emptyIdCount = 0
    fixed = fixed.replace(
        /<mxCell([^>]*)\sid\s*=\s*["']\s*["']([^>]*)>/g,
        (_match, before, after) => {
            emptyIdCount++
            const newId = `cell_${Date.now()}_${emptyIdCount}`
            return `<mxCell${before} id="${newId}"${after}>`
        },
    )
    if (emptyIdCount > 0) {
        fixes.push(`Generated ${emptyIdCount} missing ID(s)`)
    }

    return { fixed, fixes }
}

// ============================================================================
// Combined Validation and Fix
// ============================================================================

/**
 * Validates XML and attempts to fix if invalid. By default runs the strict
 * checks (unknown elements, orphan mxPoints), meant for XML the model wrote.
 * Pass strict: false for a diagram that also holds the user's own content.
 * @param xml - The XML string to validate and potentially fix
 * @returns Object with validation result, fixed XML if applicable, and fixes applied
 */
export function validateAndFixXml(
    xml: string,
    { strict = true }: { strict?: boolean } = {},
): {
    valid: boolean
    error: string | null
    fixed: string | null
    fixes: string[]
} {
    // First validation attempt
    let error = validateMxCellStructure(xml, { strict })

    if (!error) {
        return { valid: true, error: null, fixed: null, fixes: [] }
    }

    // Try to fix
    const { fixed, fixes } = autoFixXml(xml)

    // Validate the fixed version
    error = validateMxCellStructure(fixed, { strict })

    if (!error) {
        return { valid: true, error: null, fixed, fixes }
    }

    // Still invalid after fixes
    return {
        valid: false,
        error,
        fixed: fixes.length > 0 ? fixed : null,
        fixes,
    }
}
import { getAssetUrl } from "@/lib/base-path"
import type { Locale } from "@/lib/i18n/config"
import { BLANK_MXFILE } from "@/packages/mcp-server/src/pages.ts"

/** External draw.io configured at build time (cross-origin, limited features) */
const EXTERNAL_DRAWIO_URL = process.env.NEXT_PUBLIC_DRAWIO_BASE_URL || ""

/**
 * Where the editor comes from and how it starts. The web app fills it from
 * its build settings (webDrawioSource); the MCP's canvas shell from the
 * config its server writes into the page.
 */
export interface DrawioSource {
    /** The editor page: the bundled copy's index.html on this origin, or an
     * external draw.io (cross-origin, limited features) */
    editorUrl: string
    /** draw.io theme (its ui parameter); none: draw.io's default and the
     * user's own pick */
    ui?: string
    /** Language in draw.io's naming ("zh-tw"); none: draw.io's own pick */
    lang?: string
    /** No calls to external services (the desktop app) */
    offline?: boolean
    /** draw.io's custom libraries (File > New Library, Open Library from,
     * and the buttons under the shapes); the web app leaves them out */
    libraries?: boolean
}

/**
 * The web app's editor: the copy in public/drawio, served from our own
 * origin (index.html, as Next.js serves no directory indexes), or
 * NEXT_PUBLIC_DRAWIO_BASE_URL; the simple theme in the page's language.
 */
export function webDrawioSource(lang: Locale): DrawioSource {
    const isElectron = !!(window as { electronAPI?: unknown }).electronAPI
    return {
        editorUrl: EXTERNAL_DRAWIO_URL || getAssetUrl("/drawio/index.html"),
        ui: "simple",
        // draw.io names Traditional Chinese "zh-tw"
        lang: lang === "zh-Hant" ? "zh-tw" : lang,
        offline: isElectron && !EXTERNAL_DRAWIO_URL,
    }
}

/** URL of the draw.io editor iframe */
export function getDrawioSrc(source: DrawioSource, dark: boolean): string {
    const url = new URL(source.editorUrl, window.location.href)
    const params: Record<string, string> = {
        embed: "1",
        proto: "json",
        configure: "1",
    }
    // Without a fixed theme, embedded draw.io shows Extras > Theme only
    // with themes=1 (its isThemeMenuVisible)
    if (source.ui) params.ui = source.ui
    else params.themes = "1"
    Object.assign(params, {
        spin: "0",
        libraries: source.libraries ? "1" : "0",
        noSaveBtn: "1",
        noExitBtn: "1",
        saveAndExit: "0",
        // draw.io's own dark mode (switched in place later when the editor
        // can be driven directly)
        dark: dark ? "1" : "0",
    })
    if (source.lang) params.lang = source.lang
    if (source.offline) params.offline = "1"
    for (const [key, value] of Object.entries(params)) {
        url.searchParams.set(key, value)
    }
    return url.toString()
}

/**
 * Show the page (a white sheet with a grid) unless the diagram says
 * otherwise. AI output usually has a bare <mxGraphModel>, and draw.io's
 * simple UI would then show neither page nor grid.
 */
export function withPageDefaults(xml: string): string {
    return xml.replace(
        /<mxGraphModel\b([^>]*?)(\/?)>/g,
        (_match, attrs, slash) => {
            let next = attrs as string
            if (!/\spage\s*=/.test(next)) next += ' page="1"'
            if (!/\sgrid\s*=/.test(next)) next += ' grid="1"'
            if (!/\sgridSize\s*=/.test(next)) next += ' gridSize="10"'
            return `<mxGraphModel${next}${slash}>`
        },
    )
}

/** Empty document loaded when draw.io starts */
export const EMPTY_DRAWIO_DOCUMENT = withPageDefaults(BLANK_MXFILE)

/**
 * Editor defaults sent with draw.io's configure message. The simple UI turns
 * page view off for new diagrams; keep the white page on the canvas, as in
 * the classic UI.
 */
export const DRAWIO_CONFIG = {
    defaultPageVisible: true,
    defaultGridEnabled: true,
    // A loaded diagram leaves the focus where it is (draw.io focuses its
    // window otherwise, and keys typed for the chat would go to the canvas)
    noAutoFocus: true,
}

/**
