 * while draw.io is light (it puts geDarkMode on the body), so they need no
 * change when the theme switches. draw.io's link to its GitHub page (by
 * the page tabs) is hidden: on a phone it sits right above the tab bar.
 */
export const DRAWIO_CSS = `
body:not(.geDarkMode) {
    --workspace-color: #f4f5f7;
    --focus-color: #14181d;
}
body:not(.geDarkMode) .geDiagramContainer { background-color: #f4f5f7; }
body:not(.geDarkMode) .geBackgroundPage { box-shadow: 0 1px 2px rgba(20,24,29,.08), 0 12px 32px -12px rgba(20,24,29,.18) !important; }
body:not(.geDarkMode) .geSimpleMainMenu { border-bottom: 1px solid #e4e7eb !important; box-shadow: none !important; }
.geSidebarContainer[style*="width: 0px"] { border: none !important; }
a[href*="github.com/jgraph/drawio"] { display: none !important; }
`
/**
 * Direct access to the draw.io editor running in our same-origin iframe.
 *
 * draw.io has no public JavaScript API for embedders; everything here uses
 * its internal objects (EditorUi, mxGraph). Every call checks that what it
 * needs exists, so a draw.io update that renames something turns the feature
 * off (with a console warning) instead of breaking the page.
 *
 * With an external draw.io (cross-origin) none of this is available and the
 * app uses the postMessage protocol only.
 */
import { create } from "zustand"
import { isSameDocument, plainLabel, sameFileVars } from "@/lib/diagram-diff"
import { hasCells } from "@/packages/mcp-server/src/pages.ts"
import type { SelectionAnswer } from "@/packages/mcp-server/src/selection.ts"
import { type SelectedCell, useCanvasStore } from "@/stores/canvas-store"

type EditorUi = any
type FrameWindow = any

let ui: EditorUi | null = null
let win: FrameWindow | null = null
let detachListeners: (() => void) | null = null
const warned = new Set<string>()
// Keyboard shortcuts of the app that must also work while focus is inside
// the draw.io iframe (keydown events there never reach our window)
let appShortcutHandler: ((event: KeyboardEvent) => boolean) | null = null

/** The handler returns true when it handled the key */
export function setAppShortcutHandler(
    handler: ((event: KeyboardEvent) => boolean) | null,
) {
    appShortcutHandler = handler
}

function warnOnce(key: string, message: string) {
    if (warned.has(key)) return
    warned.add(key)
    console.warn(`[drawio] ${message}`)
}

export function attachEditor(editorUi: EditorUi, frameWindow: FrameWindow) {
    if (ui === editorUi) return
    detachEditor()
    ui = editorUi
    win = frameWindow
    detachListeners = installListeners()
    keepPanelsOnResize()
    closeSidePanels()
    softenGrid()
    quietUnload()
    confirmDeleteAll()
    nameEmbedFiles()
    savePdfsOnDesktop()
    useCanvasStore.getState().set({ hasEditor: true })
    syncAll()
}

// The app saves every change on its own (the web app in the browser, the
// MCP preview on its server): draw.io's "changes may not be saved" prompt
// on a reload would be wrong
function quietUnload() {
    try {
        ui.onBeforeUnload = () => undefined
    } catch {
        // ignore
    }
}

// draw.io's pages menu removes every page at once with "Delete All": ask
// first. The menu is built each time it opens; its item is wrapped then.
function confirmDeleteAll() {
    const menu = ui?.menus?.get?.("pages")
    const build = menu?.funct
    const label = win?.mxResources?.get?.("deleteAll")
    if (typeof build !== "function" || build.naiWrapped || !label) return
    const askFirst = (run: () => void) => {
        const r = win.mxResources
        if (typeof ui.confirm === "function") {
            ui.confirm(r.get("areYouSure"), run, null, label, r.get("cancel"))
        } else if (win.confirm(r.get("areYouSure"))) {
            run()
        }
    }
    const wrapped = function (this: any, popup: any, ...rest: unknown[]) {
        const addItem = popup?.addItem
        if (typeof addItem !== "function")
            return build.apply(this, [popup, ...rest])
        const own = Object.hasOwn(popup, "addItem")
        popup.addItem = function (
            this: any,
            title: unknown,
            image: unknown,
            funct: unknown,
            ...more: unknown[]
        ) {
            const action =
                title === label && typeof funct === "function"
                    ? (...args: unknown[]) => askFirst(() => funct(...args))
                    : funct
            return addItem.call(this, title, image, action, ...more)
        }
        try {
            return build.apply(this, [popup, ...rest])
        } finally {
            if (own) popup.addItem = addItem
            else delete popup.addItem
        }
    }
    wrapped.naiWrapped = true
    menu.funct = wrapped
}

// The name draw.io's own export dialogs propose; none: diagram-YYYY-MM-DD,
// as the app's export dialog has it
let fileTitle: string | null = null

/** The diagram's name, for draw.io's own export and save dialogs */
export function setFileTitle(title: string | null) {
    fileTitle = title?.trim() || null
}

// The embedded editor's file has no title (draw.io makes a new one on every
// load), so its export dialogs would propose ".drawio.png"
function nameEmbedFiles() {
    const proto = win?.EmbedFile?.prototype
    const original = proto?.getTitle
    if (typeof original !== "function" || original.naiWrapped) return
    const wrapped = function (this: any) {
        return (
            original.call(this) ||
            fileTitle ||
            `diagram-${new Date().toLocaleDateString("sv-SE")}`
        )
    }
    wrapped.naiWrapped = true
    proto.getTitle = wrapped
}

// Desktop app: draw.io makes a PDF by printing its preview window, which
// Electron sends to the system print dialog (fixed paper sizes, so the crop
// size is lost and wide diagrams are turned). Export in the PDF dialog saves
// the preview with Electron's printToPDF instead; File > Print still prints.
function savePdfsOnDesktop() {
    const save = window.electronAPI?.savePreviewAsPdf
    const dialog = win?.PrintDialog
    const printPreview = dialog?.printPreview
    if (!save || typeof printPreview !== "function" || printPreview.naiWrapped)
        return
    // Both dialogs end in printPreview: which one is open
    let forPdf = false
    for (const [name, pdf] of [
        ["exportPdf", true],
        ["print", false],
    ] as const) {
        const action = ui?.actions?.get?.(name)
        const funct = action?.funct
        if (typeof funct !== "function") continue
        action.funct = function (this: unknown, ...args: unknown[]) {
            forPdf = pdf
            return funct.apply(this, args)
        }
    }
    const wrapped = (preview: any) => {
        const wnd = preview?.wnd
        if (!forPdf || !wnd) return printPreview(preview)
        const title = ui?.getCurrentFile?.()?.getTitle?.() || "diagram"
        const run = () =>
            save(`${title}.pdf`).catch((error) => {
                console.warn(`[drawio] PDF export failed: ${error}`)
                printPreview(preview)
            })
        // As draw.io waits before printing: images and fonts in the preview
        if (typeof dialog.waitForResources === "function") {
            dialog.waitForResources(wnd, run, dialog.printTimeout)
        } else {
            run()
        }
    }
    wrapped.naiWrapped = true
    dialog.printPreview = wrapped
}

// draw.io's simple UI opens or closes its format panel and shape library
// when its window crosses a width; the user opens them from its toolbar, so
// a resize (the chat panel sliding, a narrow window) must leave them alone.
// windowResized only toggles them when it knows the previous width.
function keepPanelsOnResize() {
    const original = ui?.windowResized
    if (typeof original !== "function" || original.naiWrapped) return
    const wrapped = function (this: any, ...args: unknown[]) {
        this.lastWindowWidth = null
        return original.apply(this, args)
    }
    wrapped.naiWrapped = true
    ui.windowResized = wrapped
}

// draw.io's grid (#e6e6e6 every 10 px) is busy behind pale shapes
function softenGrid() {
    const view = graph()?.view
    if (!view) return
    try {
        view.gridColor = "#eceef1"
        view.validateBackground()
    } catch {
        // ignore
    }
}

// draw.io opens its format panel and shape library on start, which leaves
// little room for the diagram next to the chat panel; its toolbar opens them
function closeSidePanels() {
    try {
        if (isFormatPanelOpen()) ui.actions?.get?.("format")?.funct()
    } catch {
        // ignore
    }
    try {
        if (ui.sidebarWindow?.window?.isVisible?.()) {
            ui.sidebarWindow.window.setVisible(false)
        } else if (ui.isShapesPanelVisible?.()) {
            // At once, as the end of draw.io's toggleShapesPanel does: its
            // slide takes a moment, and a diagram loaded meanwhile is
            // centered in the narrower canvas
            ui.hsplitPosition = 0
            ui.refresh()
            ui.fireEvent?.(new win.mxEventObject("shapesPanelChanged"))
        }
    } catch {
        // ignore
    }
}

export function detachEditor() {
    detachListeners?.()
    detachListeners = null
    clearHighlights()
    ui = null
    win = null
    previewBase = null
    useCanvasStore.getState().set({
        hasEditor: false,
        selection: [],
        selectionRect: null,
        isFormatOpen: false,
        isDrawioPopupOpen: false,
    })
}

/** Opens draw.io's format panel, where the selection's colors are set */
export function openFormatPanel() {
    try {
        if (!isFormatPanelOpen()) ui?.actions?.get?.("format")?.funct()
    } catch {
        // ignore
    }
    syncAll()
}

function graph() {
    return ui?.editor?.graph ?? null
}

// ---------------------------------------------------------------------------
// Replacing the diagram (AI changes)
// ---------------------------------------------------------------------------

// Diagram before the current AI turn started streaming. Previews are applied
// without undo history; the final result replaces this base as one undo step.
let previewBase: string | null = null

function currentFileXml(): string | null {
    try {
        const node = ui.getXmlFileData(null, null, true)
        return win.mxUtils.getXml(node)
    } catch {
        return null
    }
}

function withoutUndo(fn: () => void) {
    const manager = ui?.editor?.undoManager
    if (!manager?.undoableEditHappened) {
        fn()
        return
    }
    const original = manager.undoableEditHappened
    manager.undoableEditHappened = () => {}
    try {
        fn()
    } finally {
        manager.undoableEditHappened = original
    }
}

/** Id of the page on the canvas, when draw.io has pages */
function currentPageId(): string | null {
    const id = ui?.currentPage?.getId?.()
    return id === undefined || id === null ? null : String(id)
}

function firstPageId(): string | null {
    const id = ui?.pages?.[0]?.getId?.()
    return id === undefined || id === null ? null : String(id)
}

/** A page's <mxGraphModel> as XML, inflated when the page is compressed */
function modelXmlOf(diagram: Element): string | null {
    const model = diagram.getElementsByTagName("mxGraphModel")[0]
    if (model) return new XMLSerializer().serializeToString(model)
    try {
        const text = diagram.textContent?.trim()
        const inflated = text ? win?.Graph?.decompress?.(text) : null
        return typeof inflated === "string" &&
            inflated.includes("<mxGraphModel")
            ? inflated
            : null
    } catch {
        return null
    }
}

/**
 * replaceDiagramData replaces the current page with one <mxGraphModel>:
 * the document's page with the canvas page's id, or its only page
 */
function pageModelOf(xml: string): string | null {
    const doc = new DOMParser().parseFromString(xml, "text/xml")
    if (doc.querySelector("parsererror")) return null
    const root = doc.documentElement
    if (root.nodeName === "mxGraphModel") return xml
    if (root.nodeName !== "mxfile") return null
    const diagrams = Array.from(root.getElementsByTagName("diagram"))
    const id = currentPageId()
    const diagram =
        diagrams.length === 1
            ? diagrams[0]
            : diagrams.find((d) => d.getAttribute("id") === id)
    return diagram ? modelXmlOf(diagram) : null
}

/**
 * The document without the current page, for comparing the other pages.
 * null when the XML is not a document; "" for a single page.
 */
function withoutCurrentPage(xml: string | null): string | null {
    if (!xml) return null
    const doc = new DOMParser().parseFromString(xml, "text/xml")
    if (doc.querySelector("parsererror")) return null
    const root = doc.documentElement
    if (root.nodeName === "mxGraphModel") return ""
    if (root.nodeName !== "mxfile") return null
    const diagrams = Array.from(root.getElementsByTagName("diagram"))
    if (diagrams.length <= 1) return ""
    const id = currentPageId()
    for (const diagram of diagrams) {
        if (diagram.getAttribute("id") === id) root.removeChild(diagram)
    }
    return new XMLSerializer().serializeToString(root)
}

/**
 * The document changes the current page only: its other pages are the
 * canvas's (same names, cells and page settings; draw.io fills in settings
 * a loaded file left out, so the text can differ)
 */
function otherPagesSame(xml: string): boolean {
    const theirs = withoutCurrentPage(xml)
    if (theirs === null) return false
    const pageCount = Array.isArray(ui.pages) ? ui.pages.length : 1
    if (pageCount <= 1 && theirs === "") return true
    const ours = withoutCurrentPage(currentFileXml())
    if (ours === null || ours === "" || theirs === "") return false
    return isSameDocument(theirs, ours)
}

function replace(xml: string) {
    const model = pageModelOf(xml)
    if (!model || typeof ui?.replaceDiagramData !== "function") {
        throw new Error("Diagram can't be replaced in place")
    }
    ui.replaceDiagramData(model)
}

/** No shapes on any layer */
function isEmptyModel(): boolean {
    const g = graph()
    const root = g?.model.getRoot()
    if (!root) return true
    for (let i = 0; i < g.model.getChildCount(root); i++) {
        if (g.model.getChildCount(g.model.getChildAt(root, i)) > 0) {
            return false
        }
    }
    return true
}

/** Whether a page has shapes; layers (cells under the root) are none */
function hasShapes(xml: string): boolean {
    const model = pageModelOf(xml)
    if (model === null) return hasCells(xml)
    const cells = new DOMParser()
        .parseFromString(model, "text/xml")
        .getElementsByTagName("mxCell")
    return Array.from(cells).some((cell) => {
        const parent = cell.getAttribute("parent")
        return parent !== null && parent !== "0"
    })
}

/**
 * Page settings draw.io applies on a full load only: replacing the page in
 * place (Editor.readGraphState) keeps the old ones. (Its adaptive colors and
 * theme stay too: a diagram the AI writes does not set them.) Takes the
 * page's mxGraphModel element; the MCP shell's sync asks the same question
 * of a document before it reaches the editor.
 */
export function hasLoadOnlySettings(model: Element): boolean {
    return (
        model.hasAttribute("backgroundImage") ||
        model.hasAttribute("extFonts") ||
        model.getAttribute("math") === "1" ||
        model.getAttribute("shadow") === "1"
    )
}

function canvasHasLoadOnlySettings(): boolean {
    const g = graph()
    return (
        !!g &&
        (!!g.backgroundImage ||
            !!g.mathEnabled ||
            !!g.shadowVisible ||
            (g.extFonts?.length ?? 0) > 0)
    )
}

/** The file variables (%name% placeholders) a document sets, if any */
function fileVars(xml: string): string | null {
    const root = new DOMParser().parseFromString(
        xml,
        "text/xml",
    ).documentElement
    return root?.nodeName === "mxfile" ? root.getAttribute("vars") : null
}

/** Can this diagram go through the editor (with undo) instead of a full load? */
export function canReplaceDiagram(xml: string): boolean {
    if (!ui) return false
    if (typeof ui.replaceDiagramData !== "function") {
        warnOnce("replace", "replaceDiagramData not found, using full loads")
        return false
    }
    // Replacing changes the current page only: a document whose other
    // pages differ from the canvas's loads in full
    if (!otherPagesSame(xml)) return false
    // Replacing the page keeps the file's variables: other ones, or none
    // over a file with some, load in full
    if (
        !sameFileVars(
            fileVars(xml),
            ui.fileNode?.getAttribute?.("vars") ?? null,
        )
    ) {
        return false
    }
    const model = pageModelOf(xml)
    // A document with them, or replacing one with them, loads in full
    return (
        model !== null &&
        !hasLoadOnlySettings(
            new DOMParser().parseFromString(model, "text/xml").documentElement,
        ) &&
        !canvasHasLoadOnlySettings()
    )
}

/** Show a streaming preview without touching the undo history */
export function previewDiagram(xml: string) {
    if (previewBase === null) previewBase = currentFileXml() ?? ""
    const wasEmpty = isEmptyModel()
    withoutUndo(() => replace(xml))
    if (wasEmpty) fitDiagram()
}

/**
 * Name and id the document gives the canvas page: of its page with that
 * id, or of its only page
 */
function pageOf(xml: string): { name: string | null; id: string | null } {
    const doc = new DOMParser().parseFromString(xml, "text/xml")
    const diagrams =
        doc.documentElement?.nodeName === "mxfile"
            ? Array.from(doc.getElementsByTagName("diagram"))
            : []
    const id = currentPageId()
    const diagram =
        diagrams.length === 1
            ? diagrams[0]
            : diagrams.find((d) => d.getAttribute("id") === id)
    return {
        name: diagram?.getAttribute("name") || null,
        id: diagram?.getAttribute("id") || null,
    }
}

/**
 * A change of the page's id for draw.io's undo history (it has none of its
 * own): execute swaps the ids, as draw.io's RenamePage does with names
 */
function changePageId(page: any, id: string) {
    let other = id
    return {
        execute() {
            const current = page.getId()
            page.node.setAttribute("id", other)
            other = current
        },
    }
}

/**
 * Apply the final AI result (or a restored version) as a single undo step,
 * page name and id included: the page gets the document's id, as a full
 * load would give it (links to the page use it). The view is fitted only
 * when the canvas was empty, so a restore keeps the user's zoom.
 */
export function commitDiagram(xml: string) {
    const wasEmpty =
        isEmptyModel() || (previewBase !== null && !hasShapes(previewBase))
    const base = previewBase ? pageModelOf(previewBase) : null
    previewBase = null
    // Undo goes back to the diagram before streaming started. draw.io's
    // ReplaceDiagram change keeps the document it replaced for undo: hand it
    // that diagram, so the canvas changes once. (Putting it back on the
    // canvas first would also send it to the app, after the result.)
    const ReplaceDiagram = win?.ReplaceDiagram
    const parse = (model: string) => win.mxUtils.parseXml(model).documentElement
    const direct = typeof ReplaceDiagram === "function" && !!win?.mxUtils
    if (base && !direct) withoutUndo(() => replace(base))
    const model = graph()?.model
    const { name, id } = pageOf(xml)
    const page = ui?.currentPage
    model?.beginUpdate()
    try {
        const next = pageModelOf(xml)
        if (direct && next) {
            const change = new ReplaceDiagram(ui, parse(next))
            model.execute(change)
            if (base) change.data = parse(base)
        } else {
            replace(xml)
        }
        if (name && page && win?.RenamePage && page.getName?.() !== name) {
            model.execute(new win.RenamePage(ui, page, name))
        }
        if (id && page?.node && page.getId?.() !== id) {
            model.execute(changePageId(page, id))
        }
    } finally {
        model?.endUpdate()
    }
    if (wasEmpty) fitDiagram()
}

/** Throw away the preview and go back to the given diagram */
export function revertPreview(targetXml: string) {
    previewBase = null
    withoutUndo(() => replace(targetXml))
}

/** Forget the preview base (new user turn) without changing the canvas */
export function resetPreview() {
    previewBase = null
}

/** Show the page with this id; false when draw.io has no such page */
export function selectPage(pageId: string): boolean {
    try {
        const page = ui?.getPageById?.(pageId)
        if (!page || typeof ui.selectPage !== "function") return false
        if (ui.currentPage !== page) ui.selectPage(page, true)
        return true
    } catch {
        return false
    }
}

// When the app last fitted the diagram on its own; a canvas resize right
// after (the chat panel sliding in) fits again, unless the user zoomed since
let lastAutoFitAt = 0

// True while fitDiagram runs: its own zoom change is not the user's
let fitting = false

/** The zoom changed: if the user did it, a later resize keeps their view */
function zoomChanged() {
    if (fitting) return
    lastAutoFitAt = 0
    lastOpenedAt = 0
}

/** Fit again if the last automatic fit just happened (layout still moving) */
export function refitIfRecent(windowMs = 1500) {
    if (Date.now() - lastOpenedAt < windowMs) {
        placeOpenedDiagram()
        return true
    }
    if (Date.now() - lastAutoFitAt < windowMs) {
        fitDiagram()
        return true
    }
    return false
}

// Room around a fitted diagram (half of this on each side)
const FIT_BORDER = 128

// When a diagram was last opened; the chat panel sliding in right after
// places it again for the canvas's final width
let lastOpenedAt = 0

/** A diagram just opened comes into view; an empty page keeps the view */
export function fitOpenedDiagram() {
    if (!graph() || isEmptyModel()) return
    lastOpenedAt = Date.now()
    placeOpenedDiagram()
}

// As draw.io opens a file: the page in the middle. Shapes that still reach
// out of view (off the page, or a page wider than the canvas) are fitted
function placeOpenedDiagram() {
    const g = graph()
    if (!g) return
    fitting = true
    try {
        ui?.resetScrollbars?.()
    } catch {
        // ignore
    } finally {
        fitting = false
    }
    const b = g.getGraphBounds()
    const c = g.container
    const left = b.x - c.scrollLeft
    const top = b.y - c.scrollTop
    const inView =
        left >= 0 &&
        top >= 0 &&
        left + b.width <= c.clientWidth &&
        top + b.height <= c.clientHeight
    if (!inView) fitDiagram()
}

/** Fit the shapes (not the whole page) into the canvas, at most at 100% */
function fitDiagram() {
    const g = graph()
    if (!g) return
    fitting = true
    try {
        const b = g.getGraphBounds()
        const { scale, translate } = g.view
        if (b && b.width > 0 && b.height > 0 && win?.mxRectangle) {
            const model = new win.mxRectangle(
                b.x / scale - translate.x,
                b.y / scale - translate.y,
                b.width / scale,
                b.height / scale,
            )
            g.fitWindow(model, FIT_BORDER, 1)
        } else if (ui?.actions?.get?.("fitWindow")) {
            ui.actions.get("fitWindow").funct()
            if (g.view.scale > 1) g.zoomTo(1, true)
        }
    } catch {
        // ignore
    } finally {
        fitting = false
    }
    // After the zoom events of the fit itself
    lastAutoFitAt = Date.now()
}

/** The canvas changed width: keep what was in the middle in the middle */
export function keepCenter(oldWidth: number, newWidth: number) {
    const container = graph()?.container
    if (!container || !oldWidth || !newWidth) return
    container.scrollLeft += (oldWidth - newWidth) / 2
}

/** An empty page goes to the middle of the canvas; false when it has shapes */
export function centerEmptyPage(): boolean {
    if (!ui || !isEmptyModel() || typeof ui.resetScrollbars !== "function") {
        return false
    }
    try {
        ui.resetScrollbars()
        return true
    } catch {
        return false
    }
}

// ---------------------------------------------------------------------------
// Highlighting what the AI changed
// ---------------------------------------------------------------------------

let highlights: any[] = []
let fadeTimer: ReturnType<typeof setTimeout> | null = null
let offerTimer: ReturnType<typeof setTimeout> | null = null
// An outline waiting for draw.io to draw the cells (highlightChangedCells)
let outlineTimer: ReturnType<typeof setTimeout> | null = null

// The outline stays this long, then fades; the canvas offers to show it
// again for a while after
const OUTLINE_MS = 3000
const FADE_MS = 400
const OFFER_MS = 6000

/**
 * The cells of an outline that faded on its own, while the canvas offers
 * to show it again (null: no offer), and draw.io's drawing area (between
 * its toolbars and panels) in the frame's pixels: its top and middle
 */
export const useFadedOutline = create<{
    ids: string[] | null
    /** The page the outline was on */
    pageId: string | null
    top: number
    middle: number | null
}>(() => ({ ids: null, pageId: null, top: 0, middle: null }))

function removeOutline() {
    if (fadeTimer) clearTimeout(fadeTimer)
    fadeTimer = null
    for (const h of highlights) {
        try {
            h.destroy()
        } catch {
            // ignore
        }
    }
    highlights = []
}

function endOffer() {
    if (offerTimer) clearTimeout(offerTimer)
    offerTimer = null
    if (useFadedOutline.getState().ids) useFadedOutline.setState({ ids: null })
}

/** Ends the outline of what the AI changed (also one still to come), and
 * the offer to show it again */
export function clearHighlights() {
    if (outlineTimer) clearTimeout(outlineTimer)
    outlineTimer = null
    removeOutline()
    endOffer()
}

/** The outline fades out; the canvas then offers to show it again */
function fadeOutline(ids: string[]) {
    for (const h of highlights) {
        const node = h.shape?.node as SVGElement | undefined
        if (!node) continue
        node.style.transition = `opacity ${FADE_MS}ms`
        node.style.opacity = "0"
    }
    fadeTimer = setTimeout(() => {
        removeOutline()
        const area = (
            graph()?.container as HTMLElement | undefined
        )?.getBoundingClientRect()
        useFadedOutline.setState({
            ids,
            pageId: currentPageId(),
            top: area?.top ?? 0,
            middle: area ? area.left + area.width / 2 : null,
        })
        offerTimer = setTimeout(endOffer, OFFER_MS)
    }, FADE_MS)
}

// Outline of changed shapes: dark enough to show on white paper and on
// draw.io's pale fills (yellow ones included)
const HIGHLIGHT_OUTLINE = "#a86b00"

/**
 * Marks changed cells for a few seconds: shapes get a soft halo plus a thin
 * outline, connectors only the outline (a halo would cover their labels and
 * arrows). Drawn over the canvas, never part of the diagram.
 */
export function highlightCells(ids: string[], color: string) {
    clearHighlights()
    const g = graph()
    if (!g || !win?.mxCellHighlight || ids.length === 0) return
    const add = (
        state: any,
        stroke: string,
        width: number,
        opacity: number,
    ) => {
        const h = new win.mxCellHighlight(g, stroke, width)
        h.opacity = opacity
        h.highlight(state)
        highlights.push(h)
    }
    for (const id of ids.slice(0, 200)) {
        const cell = g.model.getCell(id)
        const state = cell ? g.view.getState(cell) : null
        if (!state) continue
        if (!g.model.isEdge(cell)) add(state, color, 8, 18)
        add(state, HIGHLIGHT_OUTLINE, 2, 100)
    }
    if (highlights.length > 0) {
        fadeTimer = setTimeout(() => fadeOutline(ids), OUTLINE_MS)
    }
}

/**
 * Marks the cells an AI change touched in the page's marker color, once
 * draw.io has drawn them (the web app's versions and the MCP shell share
 * it). navigate (Show changes) shows that page first; the automatic outline
 * after a change leaves the user on the page they are on.
 */
export function highlightChangedCells(
    ids: string[],
    pageId?: string | null,
    { navigate = true }: { navigate?: boolean } = {},
) {
    if (ids.length === 0) {
        clearHighlights()
        return
    }
    if (outlineTimer) clearTimeout(outlineTimer)
    // No page id: the first page (as commits and versions name it)
    const page = pageId ?? firstPageId()
    if (navigate && page) selectPage(page)
    // Only on the page the change belongs to: a full load may still be
    // bringing it back (wait a little), the user may have gone to another
    // one (then nothing is drawn, as cell ids repeat across pages)
    let tries = 0
    const draw = () => {
        outlineTimer = null
        if (page && currentPageId() !== page) {
            if (++tries < 15) outlineTimer = setTimeout(draw, 100)
            return
        }
        const marker = getComputedStyle(document.documentElement)
            .getPropertyValue("--marker")
            .trim()
        highlightCells(ids, marker || "#ffd84d")
    }
    outlineTimer = setTimeout(draw, 60)
}

// ---------------------------------------------------------------------------
// Selection
// ---------------------------------------------------------------------------

function cellLabel(cell: any): string {
    const g = graph()
    let text = ""
    try {
        text = g?.convertValueToString(cell) ?? ""
    } catch {
        text = ""
    }
    return plainLabel(text)
}

function readSelection(): SelectedCell[] {
    const g = graph()
    if (!g) return []
    return (g.getSelectionCells() as any[])
        .filter((cell) => cell?.id)
        .map((cell) => ({
            id: String(cell.id),
            label: cellLabel(cell),
            isEdge: !!g.model.isEdge(cell),
        }))
}

/**
 * The selection with what an editing model needs (the MCP's get_selection):
 * the page it is on, each cell's label, an edge's ends, a shape's geometry
 * as the XML has it (relative to its container) and that container. Null
 * without an editor (a cross-origin draw.io).
 */
export function readSelectionDetails(): SelectionAnswer | null {
    const g = graph()
    if (!g) return null
    const page = ui?.currentPage
    const cells = (g.getSelectionCells() as any[])
        .filter((cell) => cell?.id)
        .map((cell) => {
            const info: SelectionAnswer["cells"][number] = {
                id: String(cell.id),
                label: cellLabel(cell),
                edge: !!g.model.isEdge(cell),
            }
            if (info.edge) {
                const source = g.model.getTerminal(cell, true)
                const target = g.model.getTerminal(cell, false)
                if (source?.id) info.source = String(source.id)
                if (target?.id) info.target = String(target.id)
            } else {
                const geo = g.getCellGeometry(cell)
                if (geo) {
                    info.geometry = {
                        x: geo.x,
                        y: geo.y,
                        width: geo.width,
                        height: geo.height,
                    }
                }
            }
            // The container the cell is in; a layer is none (and the
            // default parent is the group the user entered, if any, so it
            // cannot tell the two apart)
            const parent = g.model.getParent(cell)
            if (parent?.id && !g.model.isLayer(parent)) {
                info.parent = String(parent.id)
            }
            return info
        })
    return {
        pageId: page?.getId ? String(page.getId()) : null,
        pageName: page?.getName ? String(page.getName()) : null,
        cells,
    }
}

function readSelectionRect() {
    const g = graph()
    if (!g || g.isSelectionEmpty()) return null
    const cells = g.getSelectionCells()
    const bounds = g.view.getBounds(cells)
    if (!bounds) return null
    const container = g.container as HTMLElement
    const rect = container.getBoundingClientRect()
    return {
        x: rect.left + bounds.x - container.scrollLeft,
        y: rect.top + bounds.y - container.scrollTop,
        width: bounds.width,
        height: bounds.height,
    }
}

// ---------------------------------------------------------------------------
// Keeping the store in sync
// ---------------------------------------------------------------------------

function syncSelectionRect() {
    useCanvasStore.getState().set({ selectionRect: readSelectionRect() })
}

function syncAll() {
    if (!ui) return
    const g = graph()
    useCanvasStore.getState().set({
        currentPageId: ui.currentPage?.getId
            ? String(ui.currentPage.getId())
            : null,
        selection: readSelection(),
        selectionRect: readSelectionRect(),
        isFreehand: !!g?.freehand?.isDrawing?.(),
        isFormatOpen: isFormatPanelOpen(),
    })
}

function isFormatPanelOpen(): boolean {
    try {
        if (typeof ui.isFormatPanelVisible === "function") {
            return !!ui.isFormatPanelVisible()
        }
        return (ui.formatWidth ?? 0) > 0
    } catch {
        return false
    }
}

function installListeners(): () => void {
    const g = graph()
    if (!g || !win?.mxEvent) return () => {}
    const mxEvent = win.mxEvent
    const cleanups: (() => void)[] = []

    const listen = (source: any, name: string, handler: () => void) => {
        if (!source?.addListener) return
        source.addListener(name, handler)
        cleanups.push(() => source.removeListener(handler))
    }

    // Any user action ends the "what the AI just changed" highlight: a
    // click on the canvas, a selection, another page
    const onSelection = () => {
        clearHighlights()
        syncAll()
    }
    const onScale = () => {
        zoomChanged()
        syncSelectionRect()
    }

    listen(g.getSelectionModel(), mxEvent.CHANGE, onSelection)
    listen(g.model, mxEvent.CHANGE, syncAll)
    // Drawing started or stopped: the "ask AI" button hides meanwhile
    listen(g, "freehandStateChanged", syncAll)
    // The format panel opened or closed (its toolbar button, Ctrl+Shift+P)
    listen(ui, "formatWidthChanged", syncAll)
    listen(g.view, mxEvent.SCALE, onScale)
    listen(g.view, mxEvent.TRANSLATE, syncSelectionRect)
    listen(g.view, mxEvent.SCALE_AND_TRANSLATE, onScale)
    // Another page ends the outline on screen, but not one still to come:
    // a full load that restores the AI's page fires this too
    listen(ui.editor, "pageSelected", () => {
        removeOutline()
        endOffer()
        syncAll()
    })

    // draw.io closes its menus on a press inside its own page only; Escape
    // and a press in the app close them too
    const closeMenus = () => {
        try {
            ui?.hideCurrentMenu?.()
        } catch {
            // ignore
        }
    }
    const onAppKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape") closeMenus()
    }
    document.addEventListener("pointerdown", closeMenus, true)
    document.addEventListener("keydown", onAppKeyDown, true)
    cleanups.push(() => {
        document.removeEventListener("pointerdown", closeMenus, true)
        document.removeEventListener("keydown", onAppKeyDown, true)
    })

    // Capture phase, so the app shortcut wins before draw.io's key handler
    const onKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape") closeMenus()
        if (appShortcutHandler?.(event)) {
            event.preventDefault()
            event.stopPropagation()
        }
    }
    const frameDocument = win.document as Document | undefined
    frameDocument?.addEventListener("keydown", onKeyDown, true)
    cleanups.push(() =>
        frameDocument?.removeEventListener("keydown", onKeyDown, true),
    )

    // draw.io adds its menus and dialogs to its body, and the shape picker
    // (from the arrows next to a selection) to the canvas, and removes them
    // when they close: the "ask AI" button over the frame must not cover them
    const body = frameDocument?.body
    const canvas = g.container as HTMLElement | undefined
    if (body && canvas && win.MutationObserver) {
        const syncPopups = () =>
            useCanvasStore.getState().set({
                isDrawioPopupOpen:
                    !!body.querySelector(
                        ":scope > .mxPopupMenu, :scope > .geDialog",
                    ) || !!canvas.querySelector(":scope > .geShapePicker"),
            })
        const observer = new win.MutationObserver(syncPopups)
        observer.observe(body, { childList: true })
        observer.observe(canvas, { childList: true })
        cleanups.push(() => observer.disconnect())
    }

    const container = g.container as HTMLElement | undefined
    container?.addEventListener("scroll", syncSelectionRect, { passive: true })
    container?.addEventListener("pointerdown", clearHighlights, true)
    cleanups.push(() => {
        container?.removeEventListener("scroll", syncSelectionRect)
        container?.removeEventListener("pointerdown", clearHighlights, true)
    })

    return () => {
        for (const cleanup of cleanups) cleanup()
    }
}

/**
 * Finds the EditorUi instance inside a same-origin draw.io iframe.
 *
 * draw.io keeps no global reference to it, so we wrap prototype methods it
 * calls on startup and after every load; the first call hands us `this`.
 * Returns false when the frame is cross-origin.
 */
export function watchForEditorUi(
    frameWindow: Window,
    onFound: (editorUi: EditorUi) => void,
): boolean {
    let w: any
    try {
        w = frameWindow as any
        // Throws for a cross-origin frame
        void w.document
    } catch {
        return false
    }
    const hook = (proto: any, method: string) => {
        if (!proto || typeof proto[method] !== "function") return
        if (proto[method].__naiWrapped) return
        const original = proto[method]
        const wrapped = function (this: any, ...args: any[]) {
            onFound(this)
            return original.apply(this, args)
        }
        ;(wrapped as any).__naiWrapped = true
        proto[method] = wrapped
    }
    hook(w.EditorUi?.prototype, "updateActionStates")
    hook(w.App?.prototype, "fileLoaded")
    hook(w.EditorUi?.prototype, "fileLoaded")
    return true
}
import {
    fileVars,
    modelOfPage,
    pageElement,
    parseXml,
} from "@/lib/diagram-pages"

/** What changed on one page between two versions of a diagram */
export interface ChangeSummary {
    shapesAdded: number
    shapesRemoved: number
    shapesChanged: number
    edgesAdded: number
    edgesRemoved: number
    edgesChanged: number
}

export interface DiagramDiff {
    summary: ChangeSummary
    /** Ids of cells that were added or changed (for highlighting) */
    touchedIds: string[]
    /** The diagram before had no shapes or connectors */
    fromScratch: boolean
}

export const EMPTY_SUMMARY: ChangeSummary = {
    shapesAdded: 0,
    shapesRemoved: 0,
    shapesChanged: 0,
    edgesAdded: 0,
    edgesRemoved: 0,
    edgesChanged: 0,
}

interface CellInfo {
    isEdge: boolean
    signature: string
}

/**
 * A page's mxGraphModel element, whatever wrapper the XML has: the page
 * with this id, else the first
 */
function pageModel(xml: string, pageId?: string | null): Element | null {
    const doc = parseXml(xml)
    if (!doc) return null
    const diagram = pageElement(doc, pageId)
    if (diagram) return modelOfPage(diagram)
    return doc.querySelector("mxGraphModel") ?? doc.documentElement
}

// Values draw.io leaves out when it saves: the model may write them
const DEFAULT_VALUES: Record<string, Record<string, string>> = {
    mxCell: {
        vertex: "0",
        edge: "0",
        connectable: "1",
        visible: "1",
        collapsed: "0",
        style: "",
    },
    mxGeometry: { x: "0", y: "0", width: "0", height: "0", relative: "0" },
    mxPoint: { x: "0", y: "0" },
}
// Numbers draw.io writes back in their shortest form ("40.0" is "40"), on
// the elements that hold a position or size (a wrapper's "x" is the
// user's own data, shown as written)
const NUMBERS = new Set(["x", "y", "width", "height"])
const GEOMETRY = new Set(["mxGeometry", "mxPoint", "mxRectangle"])

/**
 * A style as draw.io reads it (mxStylesheet.getCellStyle): entries apply in
 * order and empty ones do nothing; a leading ";" leaves the default out
 */
function normalStyle(style: string): string {
    const entries = style.split(";").filter((entry) => entry.trim() !== "")
    return (style.startsWith(";") ? ";" : "") + entries.join(";")
}

/**
 * What a cell is, independent of how the XML was written: the same cell
 * saved by draw.io and written by the model can order attributes
 * differently, and draw.io drops values that are the default. Style
 * entries keep their order, which counts.
 */
function signatureOf(node: Element): string {
    const defaults = DEFAULT_VALUES[node.tagName] ?? {}
    const attrs = Array.from(node.attributes)
        .flatMap((a) => {
            let value = a.value
            // A cell's style (a wrapper's "style" is the user's own data)
            if (a.name === "style" && node.tagName === "mxCell") {
                value = normalStyle(value)
            } else if (
                GEOMETRY.has(node.tagName) &&
                NUMBERS.has(a.name) &&
                value.trim() !== ""
            ) {
                const n = Number(value)
                if (Number.isFinite(n)) value = String(n)
            }
            if (defaults[a.name] === value) return []
            return [[a.name, value]]
        })
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    // As JSON: a value can hold any text, also "name=value" pairs
    return JSON.stringify([
        node.tagName,
        attrs,
        Array.from(node.children).map(signatureOf),
    ])
}

/** The cells of a page, layers included, with the element that holds each */
function cellsIn(model: Element | null) {
    if (!model) return []
    return Array.from(model.getElementsByTagName("mxCell")).flatMap((cell) => {
        // Cells with links or custom data are wrapped; the wrapper holds the id
        const wrapper = cell.parentElement
        const isWrapped =
            wrapper?.tagName === "object" || wrapper?.tagName === "UserObject"
        const id = cell.getAttribute("id") || wrapper?.getAttribute("id")
        if (!id) return []
        return [{ id, cell, node: isWrapped && wrapper ? wrapper : cell }]
    })
}

/** Shapes and connectors of one page (not the root and its layers) */
function collectCells(
    xml: string,
    pageId?: string | null,
): Map<string, CellInfo> {
    const cells = new Map<string, CellInfo>()
    for (const { id, cell, node } of cellsIn(pageModel(xml, pageId))) {
        if (id === "0" || cell.getAttribute("parent") === "0") continue
        cells.set(id, {
            isEdge: cell.getAttribute("edge") === "1",
            signature: signatureOf(node),
        })
    }
    return cells
}

/** The document has pages, and none with this id */
function lacksPage(xml: string, pageId: string): boolean {
    const doc = parseXml(xml)
    const diagrams = doc ? Array.from(doc.getElementsByTagName("diagram")) : []
    return (
        diagrams.length > 0 &&
        !diagrams.some((diagram) => diagram.getAttribute("id") === pageId)
    )
}

/**
 * What changed on one page (the first when no id is given). A page the
 * document before did not have is new: all of its cells were added (it is
 * not compared with the first page).
 */
export function diffDiagrams(
    beforeXml: string,
    afterXml: string,
    pageId?: string | null,
): DiagramDiff {
    const isNewPage =
        !!pageId && lacksPage(beforeXml, pageId) && !lacksPage(afterXml, pageId)
    const before = isNewPage
        ? new Map<string, CellInfo>()
        : collectCells(beforeXml, pageId)
    const after = collectCells(afterXml, pageId)
    const summary: ChangeSummary = { ...EMPTY_SUMMARY }
    const touchedIds: string[] = []

    for (const [id, cell] of after) {
        const old = before.get(id)
        if (!old) {
            touchedIds.push(id)
            if (cell.isEdge) summary.edgesAdded++
            else summary.shapesAdded++
        } else if (old.signature !== cell.signature) {
            touchedIds.push(id)
            if (cell.isEdge) summary.edgesChanged++
            else summary.shapesChanged++
        }
    }
    for (const [id, cell] of before) {
        if (after.has(id)) continue
        if (cell.isEdge) summary.edgesRemoved++
        else summary.shapesRemoved++
    }
    return { summary, touchedIds, fromScratch: before.size === 0 }
}

/** A label as plain text: labels can hold HTML; long ones are cut */
export function plainLabel(text: string, max = 80): string {
    const plain = text
        .replace(/<br\s*\/?>/gi, " ")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/g, " ")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/\s+/g, " ")
        .trim()
    return plain.length > max ? `${plain.slice(0, max)}…` : plain
}

/**
 * The labels of the shapes among these cells on one page (the first when
 * no id is given), in the order of the ids. Connectors and their labels
 * ("Yes", "No") are left out, as are shapes without a label.
 */
export function cellLabels(
    xml: string,
    ids: string[],
    pageId?: string | null,
): string[] {
    const cells = cellsIn(pageModel(xml, pageId))
    const edges = new Set(
        cells
            .filter(({ cell }) => cell.getAttribute("edge") === "1")
            .map(({ id }) => id),
    )
    const labels = new Map<string, string>()
    for (const { id, cell, node } of cells) {
        if (edges.has(id) || edges.has(cell.getAttribute("parent") ?? "")) {
            continue
        }
        // A wrapper keeps the label in its own attribute
        const value =
            node === cell
                ? cell.getAttribute("value")
                : node.getAttribute("label")
        const label = plainLabel(value ?? "", 40)
        if (label) labels.set(id, label)
    }
    return ids.flatMap((id) => labels.get(id) ?? [])
}

// Where the view was scrolled to, saved with the page; not a change
const VIEW_ATTRIBUTES = new Set(["dx", "dy"])

// A page setting written on one side only is draw.io's default being
// filled in when the other side has that default; an empty list: any value
// is a change. Settings not listed are not compared then, like the paper
// size: a page without it keeps the canvas's (draw.io's readGraphState).
const PAGE_DEFAULTS: Record<string, string[]> = {
    background: ["none"],
    backgroundImage: [],
    extFonts: [],
    math: ["0"],
    shadow: ["0"],
    page: ["1"],
    pageScale: ["1"],
    grid: ["1"],
    gridSize: ["10"],
    guides: ["1"],
    tooltips: ["1"],
    connect: ["1"],
    arrows: ["1"],
    fold: ["1"],
}

// Settings draw.io reads as numbers (Editor.readGraphState): "10.0" is 10
const PAGE_NUMBERS = new Set([
    "gridSize",
    "pageScale",
    "pageWidth",
    "pageHeight",
])

function samePageSettings(a: Element, b: Element): boolean {
    const names = new Set(
        [...Array.from(a.attributes), ...Array.from(b.attributes)].map(
            (attr) => attr.name,
        ),
    )
    const read = (page: Element, name: string) => {
        const value = page.getAttribute(name)
        if (value === null || !PAGE_NUMBERS.has(name) || !value.trim()) {
            return value
        }
        const n = Number(value)
        return Number.isFinite(n) ? String(n) : value
    }
    for (const name of names) {
        if (VIEW_ATTRIBUTES.has(name)) continue
        const va = read(a, name)
        const vb = read(b, name)
        if (va !== null && vb !== null) {
            if (va !== vb) return false
            continue
        }
        const defaults = PAGE_DEFAULTS[name]
        if (defaults && !defaults.includes((va ?? vb) as string)) return false
    }
    return true
}

/**
 * Every cell of a page, layers included, and the order of each parent's
 * children (which shape is in front)
 */
function contentOf(model: Element | null) {
    const cells = new Map<string, string>()
    const children = new Map<string, string[]>()
    for (const { id, cell, node } of cellsIn(model)) {
        cells.set(id, signatureOf(node))
        const parent = cell.getAttribute("parent") ?? ""
        children.set(parent, [...(children.get(parent) ?? []), id])
    }
    return { cells, children }
}

function sameContent(a: Element | null, b: Element | null): boolean {
    const ca = contentOf(a)
    const cb = contentOf(b)
    if (ca.cells.size !== cb.cells.size) return false
    for (const [id, signature] of ca.cells) {
        if (cb.cells.get(id) !== signature) return false
    }
    for (const [parent, ids] of ca.children) {
        if (cb.children.get(parent)?.join("\n") !== ids.join("\n")) {
            return false
        }
    }
    return true
}

/**
 * File variables (%name% placeholders) as draw.io reads them, from JSON:
 * the same names and values in any order; none is the same as "{}"
 */
export function sameFileVars(a: string | null, b: string | null): boolean {
    if (a === b) return true
    try {
        // By name: names are unique, and a pair's text can look like another's
        const sorted = (vars: string | null) =>
            JSON.stringify(
                Object.entries(JSON.parse(vars ?? "{}")).sort(([a], [b]) =>
                    a < b ? -1 : a > b ? 1 : 0,
                ),
            )
        return sorted(a) === sorted(b)
    } catch {
        return false
    }
}

/**
 * Whether two documents hold the same pages (names, cells, their order),
 * page settings and file variables. This is the web app's one rule for "is
 * this version on the canvas" (versions, compare, one-step commits). The
 * MCP server's edit gate has its own (contentFingerprint): it compares the
 * cells as written, and leaves page settings and file variables out. The
 * two disagree both ways (a background change is a difference only here;
 * a geometry written "40.0" and "40" is one only there), so neither is a
 * subset of the other.
 */
export function isSameDocument(a: string, b: string): boolean {
    const pagesOf = (doc: Document) => {
        const diagrams = Array.from(doc.getElementsByTagName("diagram"))
        if (diagrams.length === 0) {
            return [{ name: null, model: doc.querySelector("mxGraphModel") }]
        }
        return diagrams.map((d) => ({
            name: d.getAttribute("name"),
            model: modelOfPage(d),
        }))
    }
    const docA = parseXml(a)
    const docB = parseXml(b)
    if (!docA || !docB) return a === b
    if (!sameFileVars(fileVars(docA), fileVars(docB))) return false
    const pagesA = pagesOf(docA)
    const pagesB = pagesOf(docB)
    if (pagesA.length !== pagesB.length) return false
    return pagesA.every((pageA, i) => {
        const pageB = pagesB[i]
        if (pageA.name !== null && pageB.name !== null) {
            if (pageA.name !== pageB.name) return false
        }
        if (pageA.model && pageB.model) {
            if (!samePageSettings(pageA.model, pageB.model)) return false
        }
        return sameContent(pageA.model, pageB.model)
    })
}
